\newcommand{\IllusieTransitivityTriangle}{%
  \begin{center}
  \begin{tikzpicture}[
    >=stealth,
    line width=0.45pt,
    every node/.style={font=\rmfamily\fontsize{8.15}{9}\selectfont}
  ]
    \node (xy) at (0,1.05) {$L_{X/Y}$};
    \node (fyz) at (-1.55,-0.45) {$\mathbf L f^{*}L_{Y/Z}$};
    \node (xz) at (1.45,-0.45) {$L_{X/Z}$};
    \draw[->] (xy) -- (fyz);
    \draw[->] (fyz) -- (xz);
    \draw[->] (xz) -- (xy);
  \end{tikzpicture}
  \end{center}%
}

