    \draw[->] (BL) -- (BC);
    \draw[->] (BC) -- (BR);
    \draw[->] (TL) -- (ML);
    \draw[->] (TC) -- (MC);
    \draw[->] (TR) -- (MR);
    \draw[->] (BL) -- (ML);
    \draw[->] (BC) -- (MC);
    \draw[->] (BR) -- (MR);
  \end{tikzpicture}
  \end{center}%
}

