\begin{illusiebodypage}{illusie:I:ch1:p087}
\label{rf-source-87}


\ReflowBodyFont 



\newcommand{\IllusiePoneOhFiveDisplay}[2]{\par\vspace{0.25bp}\noindent\makebox[0pt][l]{#1}\makebox[\dimexpr\linewidth-10bp\relax][c]{$\displaystyle #2$}\par\vspace{0.25bp}}

\phantomsection\hypertarget{illusie:I:ch1:p087:spectral-sequence-3.3.3.1}{}%
\IllusiePoneOhFiveDisplay{}{E_{p,q}^{2}=H_p\!\left(\operatorname{Tor}_{q}^{A}(E,F)\right)\Longrightarrow H_*\!\left(E\overset{\ell}{\otimes}_{A}F\right).}
\phantomsection\hypertarget{illusie:I:ch1:p087:proof-3.3.3.1}{}%
\noindent\uline{Preuve}. On a (3.3.2.5) \(E\overset{\ell}{\otimes}F=\Delta(E\overset{L}{\otimes}F)\), d'où, par Eilenberg-Zilber, \(H_*(E\overset{\ell}{\otimes}F)\mathrel{\sim}H_*(E\overset{L}{\otimes}F)\). Il suffit donc d'écrire la suite spectrale \(H_p^{\mathrm H}H_q^{\mathrm V}\Longrightarrow H_*\) relative au bicomplexe \(E\overset{L}{\otimes}F\). Pour la fonctorialité, on peut utiliser le calcul de \(E\overset{L}{\otimes}F\) à l'aide de la résolution libre standard.

\phantomsection\hypertarget{illusie:I:ch1:p087:proposition-3.3.3.2}{}%
\noindent\uline{Proposition} 3.3.3.2.\quad (cf. (loc. cit.)). \uline{Sous les hypothèses de (3.3.3.1), il existe une suite spectrale du premier quadrant, à valeurs dans la catégorie des} \(H_*(A)\)-\uline{modules, fonctorielle en chacun de ses arguments}
\phantomsection\hypertarget{illusie:I:ch1:p087:spectral-sequence-3.3.3.2}{}%
\IllusiePoneOhFiveDisplay{}{E_{pq}^{2}=k_q\operatorname{Tor}_{p}^{H_*(A)}\bigl(H_*(E),H_*(F)\bigr)\Longrightarrow H_*\!\left(E\overset{\ell}{\otimes}F\right),}
\noindent\uline{où} \(k_q\) \uline{désigne la partie homogène de degré} \(q\) \uline{du} \(H_*(A)\)-\uline{module gradué} \(\operatorname{Tor}_{p}^{H_*(A)}(H_*(E),H_*(F))\) (\uline{rappelons (3.1.3) que} \(H_*(A)\) \uline{est un anneau gradué anticommutatif et} \(H_*(E)\) (resp. \(H_*(F)\)) \uline{un} \(H_*(A)\)-\uline{module gradué} \({}^{(1)}\)).

\phantomsection\hypertarget{illusie:I:ch1:p087:shuffle-preliminaries}{}%
\noindent\hspace{42bp}La preuve de (3.3.3.2) sera donnée après quelques préliminaires. Pour \(L,M\in\operatorname{ob}A\text{-}\mathrm{Mod}\), on définit, à l'aide des ``shuffles'' (3.1.3), un homomorphisme canonique fonctoriel
\phantomsection\hypertarget{illusie:I:ch1:p087:eq-3.3.3.3}{}%
\IllusiePoneOhFiveDisplay{(3.3.3.3)}{L^{\sim}\otimes_{A^{\sim}}M^{\sim}\longrightarrow(L\otimes_A M)^{\sim},}
\noindent où le premier membre désigne le produit tensoriel habituel des modules différentiels gradués \(L^{\sim}\) et \(M^{\sim}\) sur l'anneau différentiel gradué \(A^{\sim}\). On en déduit un homomorphisme canonique fonctoriel
\phantomsection\hypertarget{illusie:I:ch1:p087:eq-3.3.3.4}{}%
\IllusiePoneOhFiveDisplay{(3.3.3.4)}{H_*(L)\otimes_{H_*(A)}H_*(M)\longrightarrow H_*(L\otimes_A M).}

\phantomsection\hypertarget{illusie:I:ch1:p087:definition-3.3.3.5}{}%
\noindent\uline{Définition} 3.3.3.5.\quad \uline{Nous dirons qu'un} \(A\)-\uline{module} \(M\) \uline{est spécial s'il existe un} \(\mathbb Z\)-\uline{module simplicial plat} \(P\), \uline{dont l'homologie est plate sur} \(\mathbb Z\), \uline{tel que} \(M\simeq A\otimes_{\mathbb Z}P\).
\phantomsection\hypertarget{illusie:I:ch1:p087:footnote-1}{}%
\noindent\rule{112bp}{0.35bp}\par
\noindent\({}^{(1)}\) On renvoie à (IV 1.2.3) pour la définition du produit tensoriel dérivé de modules gradués sur un anneau gradué.\vspace{5bp}

