\phantomsection\hypertarget{illusie:I:ch1:p108:bigraded-leibniz-rule}{}%
\ReflowDisplay{}{d(xx')=(dx)x'+(-1)^{qn'}x(dx')}

\noindent pour $x$ et $x'$ comme plus haut. (On a une notion analogue de $A$-Algèbre
bigraduée anti-commutative pour le \uline{premier} degré, et de dérivation de bidegré
$(p,q)$ de celle-ci).

\vspace{5.0bp}
\phantomsection\hypertarget{illusie:I:ch1:p108:proposition-4.3.1.2}{}%
\noindent\uline{Proposition} 4.3.1.2.\quad
\uline{Soit} $u:E\longrightarrow F$ \uline{un morphisme de} $A$-\uline{Modules}.

\phantomsection\hypertarget{illusie:I:ch1:p108:koszul-derivation-a}{}%
\noindent\hspace{44bp}a)\quad \uline{Il existe sur l'Algèbre bigraduée}
$\Lambda E\otimes SF$ \uline{(anti-commutative pour le premier degré) une unique
$A$-dérivation} $d$ \uline{de bidegré} $(-1,1)$ \uline{telle que}

\ReflowDisplay{}{d(x\otimes1)=1\otimes ux,\qquad d(1\otimes y)=0}

\noindent \uline{pour} $x$ (resp. $y$) \uline{section de} $E$ (resp. $F$).
\uline{Elle satisfait de plus à} $dd=0$.

\phantomsection\hypertarget{illusie:I:ch1:p108:koszul-derivation-b}{}%
\noindent\hspace{44bp}b)\quad \uline{Il existe sur l'Algèbre bigraduée}
$\Gamma E\otimes\Lambda F$ \uline{(anti-commutative pour le second degré) une unique
$A$-dérivation} $d$ \uline{de bidegré} $(-1,1)$ \uline{telle que}

\ReflowDisplay{}{d\bigl(\gamma_k(x)\otimes1\bigr)=\gamma_{k-1}(x)\otimes ux,
\qquad d(1\otimes y)=0}

\noindent \uline{pour} $x$ (resp. $y$) \uline{section de} $E$ (resp. $F$),
$\gamma_k:E\longrightarrow\Gamma_A^kE$ \uline{désignant l'application canonique}.
\uline{Elle satisfait de plus à} $dd=0$.

\vspace{5.0bp}
\phantomsection\hypertarget{illusie:I:ch1:p108:proof-4.3.1.2}{}%
\noindent\hspace{44bp}La preuve se fait par l'âne qui trotte, nous l'omettrons.

\vspace{5.0bp}
\phantomsection\hypertarget{illusie:I:ch1:p108:s4.3.1.3}{}%
\noindent 4.3.1.3.\quad L'Algèbre $\Lambda E\otimes SF$ (resp.
$\Gamma E\otimes\Lambda F$), munie de la dérivation $d$ définie en (4.3.1.2) s'appelle
\uline{Algèbre} (ou \uline{complexe}) \uline{de Koszul de} $u$. On la notera
$\operatorname{Kos}_{\bullet}(u)$ (resp. $\operatorname{Kos}^{\bullet}(u)$)\({}^{(1)}\).
