\phantomsection\hypertarget{illusie:I:ch1:p110:koszul-exact-sequences}{}%
\ReflowDisplay{}{\begin{aligned}
0&\longrightarrow\Lambda^nE\longrightarrow\Lambda^{n-1}E\otimes F
\longrightarrow\cdots\longrightarrow E\otimes S^{n-1}F\longrightarrow S^nF
\longrightarrow S^nG\longrightarrow0,\\
\text{(resp. }0&\longrightarrow\Gamma^nE\longrightarrow\Gamma^nF
\longrightarrow\Gamma^{n-1}F\otimes G\longrightarrow\cdots
\longrightarrow F\otimes\Lambda^{n-1}G\longrightarrow\Lambda^nG\longrightarrow0\text{),}
\end{aligned}}

\noindent qu'on appelle \uline{suite exacte de Koszul} définie par (*).
