\phantomsection\hypertarget{illusie:I:ch1:p111:s4.3.2}{}%
\noindent 4.3.2.\quad \uline{Formules de décalage}.\quad (cf. ([24] 7.21)).

\vspace{4.0bp}
\phantomsection\hypertarget{illusie:I:ch1:p111:proposition-4.3.2.1}{}%
\noindent\uline{Proposition} 4.3.2.1.\quad \uline{Soit} $E\in\operatorname{ob}D^-(A)$.
\uline{Pour} $n\in\mathbb N^*$, \uline{il existe des isomorphismes fonctoriels
canoniques de} $D(A)$

\phantomsection\hypertarget{illusie:I:ch1:p111:shift-isomorphisms}{}%
\ReflowDisplay{}{\begin{array}{l@{\hspace{14bp}}l}
(i)&LS^n(E[1])\mathrel{\overset{\sim}{\rule[.45ex]{14bp}{.35bp}}}(L\wedge^nE)[n],\\[12bp]
(ii)&L\wedge^n(E[1])\mathrel{\overset{\sim}{\rule[.45ex]{14bp}{.35bp}}}(L\Gamma^nE)[n].
\end{array}}

\phantomsection\hypertarget{illusie:I:ch1:p111:shift-pairing-compatibility}{}%
\noindent\uline{En outre, ceux-ci sont compatibles aux accouplements} (4.2.3.6),
\uline{i.e. pour} $m\in\mathbb N^*$, \uline{on a des carrés commutatifs}\textsuperscript{(1)}

\phantomsection\hypertarget{illusie:I:ch1:p111:shift-product-square-i}{}%
\begin{center}\IllusieSymmetricShiftPairingSquare\end{center}

\phantomsection\hypertarget{illusie:I:ch1:p111:shift-product-square-ii}{}%
\begin{center}\IllusieExteriorShiftPairingSquare\end{center}

\vspace{2.0bp}
\phantomsection\hypertarget{illusie:I:ch1:p111:proof-4.3.2.1}{}%
\noindent\uline{Preuve}.\quad On peut supposer $E$ à composantes plates et borné
supérieurement. On a la suite exacte canonique

\phantomsection\hypertarget{illusie:I:ch1:p111:cone-identity-exact-sequence}{}%
\ReflowDisplay{}{(*)\qquad0\longrightarrow E\xrightarrow{\operatorname{id}}E\longrightarrow C(E)
\longrightarrow E[1]\longrightarrow0,}

\noindent où $C(E)$ désigne le cône du morphisme identique de $E$. D'où, par application
du foncteur $Ki$, une suite exacte

\phantomsection\hypertarget{illusie:I:ch1:p111:ki-cone-exact-sequence}{}%
\ReflowDisplay{}{(**)\qquad0\longrightarrow KiE\longrightarrow KiC(E)\longrightarrow Ki(E[1])
\longrightarrow0.}


\phantomsection\hypertarget{illusie:I:ch1:p111:footnote-1}{}%
\noindent\rule{120bp}{0.35bp}\par
\noindent\textsuperscript{(1)} Dans la définition des flèches horizontales inférieures on utilise
l'isomorphisme canonique (attention aux signes)
$X[m]\mathbin{\overset L\otimes}Y[n]\mathrel{\overset{\sim}{\rule[.45ex]{14bp}{.35bp}}}
(X\mathbin{\overset L\otimes}Y)[m+n]$ (cf. Verdier [27]).
\vspace{5.0bp}

