% DÉBUT DU FICHIER SOURCE tex/common/ringed_topos_squares_p119.tex
\providecommand{\IllusieSimplicialDifferentialsSquare}{%
  \begin{tikzpicture}[baseline=(current bounding box.center),>=stealth]
    \node (Bn) at (0,2.65) {$B_n$};
    \node (Bm) at (4.65,2.65) {$B_m$};
    \node (An) at (0,0) {$A_n$};
    \node (Am) at (4.65,0) {$A_m$};
    \draw[->] (Bn) -- node[above] {$B_u$} (Bm);
    \draw[->] (An) -- node[above] {$A_u$} (Am);
    \draw[->] (An) -- (Bn);
    \draw[->] (Am) -- (Bm);
    \node at (5.7,0) {$.$};
  \end{tikzpicture}%
}

\providecommand{\IllusieRingedTopoiSquare}{%
  \begin{tikzpicture}[baseline=(current bounding box.center),>=stealth]
    \node (X)  at (0,2.5) {$X$};
    \node (Xp) at (3.6,2.5) {$X'$};
    \node (Y)  at (0,0) {$Y$};
    \node (Yp) at (3.6,0) {$Y'$};
    \draw[->] (Xp) -- node[above] {$u$} (X);
    \draw[->] (Yp) -- node[above] {$v$} (Y);
    \draw[->] (X) -- node[left] {$f$} (Y);
    \draw[->] (Xp) -- node[right] {$f'$} (Yp);
  \end{tikzpicture}%
}

% FIN DU FICHIER SOURCE tex/common/ringed_topos_squares_p119.tex



\vspace{1.0bp}\ReflowBodyFont 


\newcommand{\IllusiePoneNineteenDisplay}[2]{%
  \ReflowDisplay{}{\hbox{\text{#1}\hfill$\displaystyle #2$\hfill
  \phantom{\text{#1}}}}}

\phantomsection\hypertarget{illusie:I:ch1:p119:inverse-image-differentials-cont}{}%
\noindent En particulier, la formation de $\Omega^1_{-/-}$ commute au passage aux
fibres. Autre exemple,\par

\phantomsection\hypertarget{illusie:I:ch1:p119:simplicial-rings-example}{}%
\noindent qui nous sera utile plus bas : soit $A\longrightarrow B$ un morphisme
d'Anneaux simpliciaux\par
\noindent de $T$, i.e. d'Anneaux du topos simplicial $\operatorname{Simpl}(T)$ ; alors
le $B$-Module (de\par
\noindent $\operatorname{Simpl}(T)$) $\Omega^1_{B/A}$ a pour composante de degré $n$
$\Omega^1_{B_n/A_n}$ (via l'identification (1.1.4.1)\par
\noindent appliquée au foncteur image inverse
$\operatorname{Simpl}(T)\longrightarrow T$, $X\longmapsto X_n$) ; pour\par
\noindent $u:[0,m]\longrightarrow[0,n]\in\operatorname{Fl}\,\Delta$, la flèche
$(\Omega^1_{B/A})_n\longrightarrow(\Omega^1_{B/A})_m$ correspondante\par
\noindent s'identifie à la flèche
$\Omega^1_{B_n/A_n}\longrightarrow\Omega^1_{B_m/A_m}$ définie par le carré commutatif

\phantomsection\hypertarget{illusie:I:ch1:p119:simplicial-transition-square}{}%
\begin{center}\IllusieSimplicialDifferentialsSquare\end{center}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p119:s1.1.4-ringed-topoi}{}%
\noindent 1.1.4.\quad Soit $f:X\longrightarrow X$ un morphisme de topos annelés. On
pose

\phantomsection\hypertarget{illusie:I:ch1:p119:principal-parts-ringed-topoi-1.1.4.1}{}%
\IllusiePoneNineteenDisplay{(1.1.4.1)}{%
P^n_{X/Y}=P^n_{\mathcal O_X/f^{-1}(\mathcal O_Y)},\qquad
\Omega^1_{X/Y}=\Omega^1_{\mathcal O_X/f^{-1}(\mathcal O_Y)}.}

\phantomsection\hypertarget{illusie:I:ch1:p119:principal-parts-and-differentials}{}%
\noindent On dit que $P^n_{X/Y}$ est l'Anneau des parties principales d'ordre $n$ de
$X$ sur $Y$ ;\par
\noindent le topos $X$ annelé par $P^n_{X/Y}$ s'appelle $n$-ième $Y$-voisinage
infinitésimal de $X$\par
\noindent dans la diagonale. On dit que $\Omega^1_{X/Y}$ est le Module des
différentielles (de Kähler)\par
\noindent de $X$ sur $Y$. A un carré commutatif de topos annelés\textsuperscript{(1)}

\phantomsection\hypertarget{illusie:I:ch1:p119:ringed-topoi-square-1.1.4.2}{}%
\noindent\makebox[\dimexpr\linewidth-16bp\relax][s]{(1.1.4.2)\hfill
\IllusieRingedTopoiSquare\hfill\phantom{(1.1.4.2)}}\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p119:footnote-1}{}%
\noindent\rule{72bp}{0.35bp}\par
\noindent\begin{minipage}{\dimexpr\linewidth-16bp\relax}\ReflowBodyFont 
\textsuperscript{(1)} ``commutatif'' signifie
``$u^*f^*=f'^*v^*$ à isomorphisme donné près'' ; donc plus bas\par
\noindent (1.1.4.4) n'est commutatif qu'à isomorphisme donné près.
\end{minipage}
\vspace{5bp}

