% DÉBUT DU FICHIER SOURCE tex/common/standard_resolution_functoriality_p121.tex
\providecommand{\IllusieStandardResolutionBaseSquare}{%
  \begin{tikzpicture}[baseline=(current bounding box.center),>=stealth]
    \node (B)  at (0,2.55) {$B$};
    \node (Bp) at (3.55,2.55) {$B'$};
    \node (A)  at (0,0) {$A$};
    \node (Ap) at (3.55,0) {$A'$};
    \draw[->] (B) -- (Bp);
    \draw[->] (A) -- (Ap);
    \draw[->] (A) -- (B);
    \draw[->] (Ap) -- (Bp);
    \node at (1.78,1.25) {$*$};
  \end{tikzpicture}%
}

\providecommand{\IllusieStandardResolutionFunctorialityDiagram}{%
  \begin{tikzpicture}[baseline=(P.base),>=stealth]
    \node (P)   at (0,4.45) {$P_A(B)$};
    \node (Pp)  at (5.65,4.45) {$P_{A'}(B')$};
    \node (B)   at (1.55,2.15) {$B$};
    \node (Bp)  at (6.95,2.15) {$B'$};
    \node (A)   at (1.55,0) {$A$};
    \node (Ap)  at (6.95,0) {$A'$};
    \draw[->] (P) -- (Pp);
    \draw[->] (A) -- (Ap);
    \draw[->] (P) -- (B);
    \draw[->] (Pp) -- (Bp);
    \draw[->] (A) -- (B);
    \draw[->] (Ap) -- (Bp);
    \draw[->] (A) -- (P);
    \draw[->] (Ap) -- (Pp);
    \draw[->,preaction={draw=white,line width=4bp}] (B) -- (Bp);
    \node at (4.25,0.85) {$*$};
    \node at (8.05,0) {$;$};
  \end{tikzpicture}%
}

\providecommand{\IllusieStandardResolutionRecursiveSquare}{%
  \begin{tikzpicture}[baseline=(UL.base),>=stealth]
    \node (UL) at (0,3.2) {$A[P_A(B)_{n-1}]$};
    \node (UR) at (7.05,3.2) {$A[P_{A'}(B')_{n-1}]$};
    \node (LL) at (0,0) {$A'[P_A(B)_{n-1}]$};
    \node (LR) at (7.05,0) {$A'[P_{A'}(B')_{n-1}]$};
    \draw[->] (UL) -- (UR);
    \draw[->] (UL) -- (LL);
    \draw[->] (UR) -- (LR);
    \draw[->] (LL) -- (LR);
    \draw[->] (UL) -- (LR);
    \node at (8.2,0) {$.$};
  \end{tikzpicture}%
}

% FIN DU FICHIER SOURCE tex/common/standard_resolution_functoriality_p121.tex



\vspace{5bp}\ReflowBodyFont\IllusieUprightLatinMath


\newcommand{\IllusiePoneTwentyOneDisplay}[2]{%
  \ReflowDisplay{}{\hbox to\linewidth{\text{#1}\hfill$\displaystyle #2$\hfill
  \phantom{\text{#1}}}}}

\phantomsection\hypertarget{illusie:I:ch1:p121:standard-resolution-recursion-1.2.1.1}{}%
\IllusiePoneTwentyOneDisplay{(1.2.1.1)}{%
\begin{aligned}[t]
P_A(B)_0&=A[B]\ ;\\[7bp]
P_A(B)_n&=A[P_A(B)_{n-1}]\quad\text{pour }n>0\ .
\end{aligned}}

\phantomsection\hypertarget{illusie:I:ch1:p121:standard-resolution-functoriality}{}%
\noindent Par construction, $P_A(B)$ dépend fonctoriellement de $B$ sur $A$ : à un
carré\par
\noindent commutatif d'Anneaux

\phantomsection\hypertarget{illusie:I:ch1:p121:base-change-square}{}%
\begin{center}\IllusieStandardResolutionBaseSquare\end{center}

\vspace{5bp}

\noindent correspond un diagramme commutatif

\phantomsection\hypertarget{illusie:I:ch1:p121:standard-resolution-functoriality-diagram-1.2.1.2}{}%
\vspace{5bp}\noindent\makebox[\linewidth][s]{(1.2.1.2)\hfill
\IllusieStandardResolutionFunctorialityDiagram\hfill\phantom{(1.2.1.2)}}\par

\vspace{5bp}

\phantomsection\hypertarget{illusie:I:ch1:p121:degree-n-functorial-map}{}%
\noindent la flèche $P_A(B_n)\longrightarrow P_{A'}(B')_n$ est donnée par récurrence
par la flèche oblique\par
\noindent du carré commutatif

\phantomsection\hypertarget{illusie:I:ch1:p121:recursive-free-algebra-square-1.2.1.2.1}{}%
\vspace{5bp}\noindent\makebox[\linewidth][s]{(1.2.1.2.1)\hfill
\IllusieStandardResolutionRecursiveSquare\hfill\phantom{(1.2.1.2.1)}}\par

\vspace{5bp}

\phantomsection\hypertarget{illusie:I:ch1:p121:filtered-colimit-preservation-start}{}%
\phantomsection\hypertarget{illusie:I:ch1:p121:free-and-forgetful-functors}{}%
\noindent\hspace*{38bp}{Comme le foncteur "Algèbre libre engendrée par " commute aux limites induc-}\par
\noindent{tives quelconques et le foncteur "oubli" (de la catégorie des Algèbres dans celle}

