\label{rf-source-125}



\ReflowBodyFont\IllusieUprightLatinMath

\newcommand{\IllusiePoneTwentyFiveDisplay}[2]{%
  \noindent\makebox[\dimexpr\linewidth-8bp\relax][s]{\text{#1}\hfill$\displaystyle #2$\hfill
  \phantom{\text{#1}}}\par}
\newcommand{\IllusiePoneTwentyFiveUnnumbered}[1]{%
  \noindent\makebox[\dimexpr\linewidth-8bp\relax][c]{$\displaystyle #1$}\par}

\phantomsection\hypertarget{illusie:I:ch1:p125:s1.2.4}{}%
\noindent 1.2.4.\quad Soit $A\longrightarrow B$ comme en (1.2.3). L'augmentation
$P_A(B)\longrightarrow B$ définit une\par
\noindent augmentation

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p125:cotangent-augmentation-1.2.4.1}{}%
\IllusiePoneTwentyFiveDisplay{(1.2.4.1)}{L_{B/A}\longrightarrow\Omega^1_{B/A}\ .}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p125:proposition-1.2.4.2}{}%
\noindent \uline{Proposition} 1.2.4.2.\quad \uline{La flèche}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p125:h0-cotangent-isomorphism}{}%
\IllusiePoneTwentyFiveUnnumbered{H_0(L_{B/A})\longrightarrow\Omega^1_{B/A}}

\vspace{5bp}
\noindent \uline{définie par} (1.2.4.1) \uline{est un isomorphisme.}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p125:proof-1.2.4.2}{}%
\noindent \uline{Preuve}.\quad Posons $P_A(B)=P$. Le fait que $P\longrightarrow B$ soit un quasi-isomorphisme\par
\noindent implique en particulier que la $A$-Algèbre $B$ est conoyau de la double flèche\par
\noindent $P_1\rightrightarrows P_0$. L'assertion résulte donc simplement du fait que le foncteur
$\Omega^1_{-/-}$\par
\noindent commute aux limites inductives.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p125:corollary-1.2.4.3}{}%
\noindent \uline{Corollaire} 1.2.4.3.\quad \uline{Soit} $M$ \uline{un} $B$-\uline{Module. Il existe un isomorphisme canonique}\par
\noindent \uline{fonctoriel}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p125:ext-derivations-isomorphism}{}%
\IllusiePoneTwentyFiveUnnumbered{\mathop{\mathbb E\mathrm{xt}}\nolimits^{0}_{B}(L_{B/A},M)
\xrightarrow{\ \sim\ }\operatorname{Der}_{A}(B,M)\ .}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p125:proposition-1.2.4.4}{}%
\noindent \uline{Proposition} 1.2.4.4.\quad \uline{Supposons que}
$B\xrightarrow{\sim}S_A(E)$, \uline{où} $E$ \uline{est un} $A$-\uline{Module plat.}\par
\noindent \uline{Alors} (1.2.4.1) \uline{est un quasi-isomorphisme.}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p125:proof-1.2.4.4}{}%
\setlength{\baselineskip}{19bp}
\noindent \uline{Preuve}.\quad D'après Lazard--Deligne (I 4.2.1.3), $E$ est limite d'un $T$-système inductif\par
\noindent local de Modules libres. Les limites inductives locales étant exactes (loc. cit.),\par
\noindent on peut donc, compte tenu de (1.2.3.4), supposer que $E=A^{(X)}$ pour un $X\in\operatorname{ob}T$.\par
\noindent On a donc $B\xrightarrow{\sim}A[X]$. D'après (I 1.5.3 (ii)) appliqué aux foncteurs
$T=A[-]$,\par
\noindent $U=$ ``oubli'', l'augmentation $P_A(A[X])\longrightarrow A[X]$ est un homotopisme (de $A$-Algèbres\par
\noindent simpliciales). Par suite $\Omega^1_{P/A}\longrightarrow\Omega^1_{B/A}$ (où $P=P_A(B)$) est un homotopisme de\par
\noindent $A$-Modules simpliciaux, donc en particulier un quasi-isomorphisme. Or, les composantes\par
\noindent de $P$ étant libres, $\Omega^1_{P/A}$ est, d'après (1.1.3.2), un $P$-Module plat. Il en résulte\par
\noindent (I 3.3.4.6) que $\Omega^1_{P/A}\otimes_PB\longrightarrow\Omega^1_{B/A}$ est un quasi-isomorphisme, cqfd.

