% BEGIN SOURCE tex/common/cotangent_complex_base_change_square_p126.tex
% Native commutative square (1.2.6.1), shared by all p.126 lanes.
\providecommand{\IllusieCotangentComplexBaseChangeSquare}{%
  \begin{tikzpicture}[baseline=(current bounding box.center),>=stealth]
    \node (B)  at (0,2.65) {$B$};
    \node (Bp) at (3.45,2.65) {$B'$};
    \node (A)  at (0,0) {$A$};
    \node (Ap) at (3.45,0) {$A'$};
    \draw[->] (B) -- (Bp);
    \draw[->] (A) -- (Ap);
    \draw[->] (A) -- (B);
    \draw[->] (Ap) -- (Bp);
  \end{tikzpicture}%
}

% END SOURCE tex/common/cotangent_complex_base_change_square_p126.tex


\vspace{5bp}\ReflowBodyFont 


\newcommand{\IllusiePoneTwentySixDisplay}[2]{%
  \noindent\makebox[\linewidth][s]{\text{#1}\hfill$\displaystyle #2$\hfill
  \phantom{\text{#1}}}\par}

\phantomsection\hypertarget{illusie:I:ch1:p126:s1.2.5}{}%
\noindent 1.2.5.\quad Soit $A\longrightarrow B$ un morphisme d'Anneaux simpliciaux de $T$. Alors $L_{B/A}$ est\par
\phantomsection\hypertarget{illusie:I:ch1:p126:bisimplicial-cotangent-complex}{}%
\noindent un $B$-Module bisimplicial, $B$ étant regardé comme Anneau bisimplicial trivial dans\par
\noindent la direction verticale (cf. (1.2.2)). On pose

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p126:diagonal-cotangent-complex-1.2.5.1}{}%
\IllusiePoneTwentySixDisplay{(1.2.5.1)}{%
L_{B/A}^{\Delta}=\Delta L_{B/A}=\Omega^1_{P/A}\otimes_P B\quad ,}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p126:diagonal-flatness-and-constant-case}{}%
\noindent où $P=P_A^{\Delta}(B)$ (1.2.2). C'est un $B$-Module plat, qui, lorsque $A\longrightarrow B$ est défini\par
\noindent par un morphisme d'Anneaux $A_o\longrightarrow B_o$, de $T$, coïncide avec le complexe cotangent\par
\noindent $L_{B_o/A_o}$ introduit en (1.2.3.1). La flèche (1.2.4.1), regardée comme flèche de $B$-Modules\par
\phantomsection\hypertarget{illusie:I:ch1:p126:diagonal-augmentation-restriction}{}%
\noindent bisimpliciaux, induit, par restriction à la diagonale, une flèche de $B$-Modules

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p126:diagonal-augmentation-map-1.2.5.2}{}%
\IllusiePoneTwentySixDisplay{(1.2.5.2)}{L_{B/A}^{\Delta}\longrightarrow\Omega^1_{B/A}\quad .}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p126:proposition-1.2.5.3}{}%
\noindent \uline{Proposition} 1.2.5.3.\quad \uline{Supposons que, pour chaque} $n\in\mathbf N$, \uline{il existe un} $A_n$-\uline{Module}\par
\noindent \uline{plat} $E_n$ \uline{tel que} $B_n\xrightarrow{\sim}S_{A_n}(E_n)$ \uline{(c'est le cas par exemple si} $B$ \uline{est libre sur}\par
\noindent $A$ \uline{terme à terme). Alors} (1.2.5.2) \uline{est un quasi-isomorphisme.}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p126:proof-1.2.5.3}{}%
\noindent \uline{Preuve}.\quad Posons $P=P_A(B)$. D'après (1.2.4.4), la flèche
$\Omega^1_{P/A}\otimes_P B\longrightarrow\Omega^1_{B/A}$,\par
\noindent regardée comme flèche de $B$-Modules bisimpliciaux, induit un quasi-isomorphisme\par
\noindent sur chaque colonne. La proposition en découle, grâce à Eilenberg--Zilber et une\par
\noindent suite spectrale des bicomplexes.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p126:s1.2.6}{}%
\noindent 1.2.6.\quad Soit

\phantomsection\hypertarget{illusie:I:ch1:p126:commutative-square-1.2.6.1}{}%
\vspace{5.0bp}\noindent\makebox[\linewidth][s]{\raisebox{34bp}[0pt][0pt]{(1.2.6.1)}\hfill
\IllusieCotangentComplexBaseChangeSquare\hfill\phantom{(1.2.6.1)}}\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p126:commutative-square-description}{}%
\noindent un carré commutatif d'Anneaux simpliciaux de $T$.

