\noindent \uline{Proposition} 2.1.2.\quad \uline{Le triangle distingué de} $\operatorname{D.}(C)$
\uline{associé à} $L^{\Delta}_{C/B/A}$ \uline{par le}\par
\noindent \uline{foncteur} $\chi$ \uline{de} (I 3.2.4) \uline{s'écrit, à isomorphisme canonique fonctoriel près},

\vspace{5bp}
