\newcommand{\IllusiePoneThirtyFourTagged}[2]{%
  \noindent\makebox[\dimexpr\linewidth-8bp\relax][s]{#1\hfill
  $\displaystyle #2$\hfill\phantom{#1}}\par}

\phantomsection\hypertarget{illusie:I:ch1:p134:transitivity-functoriality-cont}{}%
\noindent (relative à $A'\longrightarrow B'\longrightarrow C'$), d'où finalement un morphisme de suites exactes de
C-Modules

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p134:transitivity-sequence-map-2.1.1.6}{}%
\IllusiePoneThirtyFourTagged{(2.1.1.6)}{L^{\Delta}_{C/B/A}\longrightarrow L^{\Delta}_{C'/B'/A'}\quad ,}

\vspace{5bp}
\noindent correspondant par adjonction à un morphisme de suites exactes de $C'$-Modules (\textsuperscript{1})

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p134:adjoint-transitivity-sequence-map-2.1.1.6-prime}{}%
\IllusiePoneThirtyFourTagged{(2.1.1.6)'}{L^{\Delta}_{C/B/A}\otimes_C C'
\longrightarrow L^{\Delta}_{C'/B'/A'}\quad .}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p134:proposition-2.1.2}{}%
\noindent \uline{Proposition} 2.1.2.\quad \uline{Le triangle distingué de} $\operatorname{D.}(C)$
\uline{associé à} $L^{\Delta}_{C/B/A}$ \uline{par le}
\uline{foncteur} $\underline{\chi}$ \uline{de} (I 3.2.4) \uline{s'écrit, à isomorphisme canonique fonctoriel près},

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p134:distinguished-transitivity-triangle}{}%
\noindent\hspace{119bp}\IllusieTransitivityDistinguishedTriangle\par

\vspace{5bp}
\noindent \uline{où les flèches de degré zéro sont les images dans} $\operatorname{D.}(C)$
\uline{des flèches canoniques.}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p134:proof-2.1.2}{}%
\noindent \uline{Preuve}.\quad Par fonctorialité de (1.2.5.2), on a un diagramme commutatif canonique
fonctoriel

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p134:cotangent-differentials-comparison-diagram-star}{}%
\noindent\makebox[\dimexpr\linewidth-8bp\relax][s]{\raisebox{-5.4bp}{(*)}\hfill
\IllusieTransitivityProofDiagram\hfill\phantom{(*)}}\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p134:proof-2.1.2-cont}{}%
\noindent où la ligne du bas est (2.1.1.3). Comme $Q$ est libre terme à terme sur $P$ , la
flèche verticale de droite est un quasi-isomorphisme d'après (1.2.5.3). De même,
comme $P$ est libre terme à terme sur $A$ , $L^{\Delta}_{P/A}\longrightarrow\Omega^1_{P/A}$ est un quasi-isomorphisme,

\vfill
\phantomsection\hypertarget{illusie:I:ch1:p134:footnote-1}{}%
\noindent\rule{72bp}{0.3bp}\par

\noindent(\textsuperscript{1})\quad Ne pas oublier que (2.1.1.4) est une suite exacte de C-Modules \uline{plats}.
