\begin{illusiebodypage}{illusie:I:ch1:p136}
\label{rf-source-136}



\ReflowBodyFont\IllusieUprightLatinMath

\newcommand{\IllusiePoneThirtySixDisplay}[1]{%
  \noindent\makebox[\dimexpr\linewidth-8bp\relax][c]{$\displaystyle #1$}\par}
\newcommand{\IllusiePoneThirtySixTagged}[2]{%
  \noindent\makebox[\dimexpr\linewidth-8bp\relax][s]{#1\hfill
  $\displaystyle #2$\hfill\phantom{#1}}\par}

\phantomsection\hypertarget{illusie:I:ch1:p136:trivial-ring-transitivity-triangle-conclusion}{}%
\noindent where the degree-zero arrows ``are'' the canonical arrows; by (1.2.4.2), the corresponding\par
\noindent homology exact sequence terminates, up to canonical functorial isomorphism, in\par
\noindent sequence (1.1.2.12).

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p136:proposition-2.1.3}{}%
\noindent \uline{Proposition} 2.1.3.\quad \uline{If the vertical arrows in} (2.1.1.5) \uline{are quasi-isomorphisms}, \uline{the canonical arrow} (2.1.1.6) (respectively, (2.1.1.6)') \uline{is a quasi-isomorphism}\par
\noindent (I 3.2.4).

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p136:proof-2.1.3}{}%
\noindent \uline{Proof}.\quad It suffices to show that the arrow induced on the underlying distinguished triangles\par
\noindent is an isomorphism. In view of (2.1.2), this follows from (1.2.6.2 b)).

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p136:s2.1.4}{}%
\noindent 2.1.4.\quad Let $\Omega^1_{C/B/A}$ denote sequence (1.1.2.12) relative to (2.1.1.1):

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p136:homology-transitivity-sequence}{}%
\IllusiePoneThirtySixDisplay{0\longrightarrow\Omega^1_{B/A}\otimes_B C
\longrightarrow\Omega^1_{C/A}\longrightarrow\Omega^1_{C/B}\longrightarrow0\quad ,}

\vspace{5bp}
\noindent which is exact except possibly at $\Omega^1_{B/A}\otimes_B C$. Diagram (2.1.1.2) canonically defines\par
\noindent an arrow

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p136:cotangent-to-homology-map-2.1.4.1}{}%
\IllusiePoneThirtySixTagged{(2.1.4.1)}{L^{\Delta}_{C/B/A}\longrightarrow\Omega^1_{C/B/A}\quad .}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p136:free-case-quasi-isomorphism}{}%
\noindent Suppose that $B$ is free over $A$ degreewise and that $C$ is free over $B$ degreewise. Then\par
\noindent the sequence $\Omega^1_{C/B/A}$ is exact, and (1.2.5.3) implies that (2.1.4.1) is a\par
\noindent quasi-isomorphism (I 3.2.4). Combining this remark with (2.1.3), we obtain:

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p136:corollary-2.1.4.2}{}%
\noindent \uline{Corollary} 2.1.4.2.\quad \uline{Suppose that the vertical arrows in} (2.1.1.5) \uline{are quasi-isomorphisms,}\par
\noindent \uline{that} $B$ \uline{is free over} $A$ \uline{degreewise, and that} $C$ \uline{is free over} $B$ \uline{degreewise. There is then}\par
\noindent \uline{a canonical isomorphism in} $\operatorname{VT.}(C')$ (I 3.2.4)

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p136:corollary-base-change-isomorphism}{}%
\IllusiePoneThirtySixDisplay{L^{\Delta}_{C'/B'/A'}\mathrel{\overset{\sim}{\rule[.45ex]{14bp}{.35bp}}}
\Omega^1_{C/B/A}\otimes_C C'\quad .}

