\phantomsection\hypertarget{illusie:I:ch1:p137:s2.1.5}{}%
\noindent 2.1.5.\quad Soient

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p137:composable-ringed-topoi-2.1.5.1}{}%
\IllusiePoneThirtySevenTagged{(2.1.5.1)}{X\xrightarrow{\ f\ }Y\xrightarrow{\ g\ }Z}

\vspace{5bp}
\noindent des morphismes de topos annelés. La suite exacte de $\mathcal O_X$-modules simpliciaux

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p137:relative-transitivity-sequence-2.1.5.2}{}%
\IllusiePoneThirtySevenTagged{(2.1.5.2)}{L_{X/Y/Z}
=L_{\mathcal O_X/f^{-1}(\mathcal O_Y)/(gf)^{-1}(\mathcal O_Z)}}

\vspace{5bp}
\noindent est appelée \uline{suite exacte} (ou \uline{vrai triangle}) \uline{de transitivité relative} à (2.1.5.1).\par
\phantomsection\hypertarget{illusie:I:ch1:p137:relative-transitivity-functoriality}{}%
\noindent Elle dépend fonctoriellement de (2.1.5.1) : un diagramme commutatif

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p137:ringed-topoi-diagram-2.1.5.3}{}%
\IllusiePoneThirtySevenDiagram{(2.1.5.3)}{\IllusieRingedTopoiTransitivityDiagram}

\vspace{5bp}
