\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p137:structure-sheaf-diagram-2.1.5.4}{}%
\IllusiePoneThirtySevenDiagram{(2.1.5.4)}{\IllusieStructureSheafTransitivityDiagram}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p137:coefficient-identifications}{}%
\noindent où $C'=\mathcal O_{X'}$, $B'=f'^{-1}(\mathcal O_{Y'})$, $A'=(g'f')^{-1}(\mathcal O_{Z'})$, $C=u^{-1}(\mathcal O_Z)$, $B=u^{-1}f^{-1}(\mathcal O_Y)$,\par
\vspace{3.5bp}
\noindent $A=u^{-1}(gf)^{-1}\mathcal O_Z$, d'où, par (2.1.1.6)', compte tenu de (1.2.3.5), un morphisme

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p137:relative-transitivity-map-2.1.5.5}{}%
\IllusiePoneThirtySevenTagged{(2.1.5.5)}{u^*L_{X/Y/Z}\longrightarrow L_{X'/Y'/Z'}\quad .}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p137:composition-coherence}{}%
\noindent Pour un « composé » de deux diagrammes (2.1.5.3), on a une transitivité qu'on laisse\par
\vspace{1.6bp}
\noindent au lecteur le soin d'expliciter.

\vspace{3.6bp}
\phantomsection\hypertarget{illusie:I:ch1:p137:distinguished-triangle-intro}{}%
\noindent\hspace*{55bp}D'après (2.1.2), le triangle distingué de $\operatorname{D}(X)$ associé à $L_{X/Y/Z}$ s'écrit,\par
\vspace{2.0bp}
\noindent à isomorphisme canonique fonctoriel près,

