\IllusiePoneFortyOneMapDisplay{(i)}{u^*L_{X/Y}\longrightarrow L_{X'/Y'}\quad ,}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:cotangent-transitivity-map-ii}{}%
\IllusiePoneFortyOneMapDisplay{(ii)}{u^*L_{X/Y}\oplus f'^*L_{Y'/Y}\longrightarrow L_{X'/Y}}

\vspace{5bp}
\noindent \uline{sont des quasi-isomorphismes}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:proof-2.2.3}{}%
\noindent \uline{Preuve}. Posons $B\otimes_A A'=B_1$. Le triangle de transitivité relatif à
