\IllusiePoneFortyOneDisplay{L_{B_1/A'}\otimes_{B_1}B'\longrightarrow L_{B'/A'}
\quad (\text{resp. }L_{B_1/A}\otimes_{B_1}B'\longrightarrow L_{B'/A})}

\vspace{5bp}
\noindent est un quasi-isomorphisme. D'après (2.2.1), la flèche canonique

\vspace{5bp}
