\noindent\makebox[\dimexpr\linewidth-6bp\relax][c]{\hspace*{6bp}\IllusieBaseChangeCorollaryRingSquarePOneFortyOne\hspace*{-6bp}}\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:corollary-2.2.3-cont}{}%
\noindent \uline{On suppose qu'on a} $\operatorname{Tor}^{A}_q(B,A')=0$ \uline{pour} $q>0$ , \uline{et}
$L_{B'/B\otimes_A A'}=0$ . \uline{Alors les}\par
\noindent \uline{flèches canoniques}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:cotangent-base-change-map-i}{}%
\IllusiePoneFortyOneMapDisplay{(i)}{u^*L_{X/Y}\longrightarrow L_{X'/Y'}\quad ,}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:cotangent-transitivity-map-ii}{}%
\IllusiePoneFortyOneMapDisplay{(ii)}{u^*L_{X/Y}\oplus f'^*L_{Y'/Y}\longrightarrow L_{X'/Y}}

\vspace{5bp}
\noindent \uline{sont des quasi-isomorphismes}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:proof-2.2.3}{}%
\noindent \uline{Preuve}. Posons $B\otimes_A A'=B_1$ . Le triangle de transitivité relatif à
$A'\longrightarrow B_1\longrightarrow B'$\par
\noindent (resp. $A\longrightarrow B_1\longrightarrow B'$) montre que la flèche canonique

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:transitivity-comparison-over-a-prime}{}%
\IllusiePoneFortyOneDisplay{L_{B_1/A'}\otimes_{B_1}B'\longrightarrow L_{B'/A'}
\quad (\text{resp. }L_{B_1/A}\otimes_{B_1}B'\longrightarrow L_{B'/A})}

\vspace{5bp}
\noindent est un quasi-isomorphisme. D'après (2.2.1), la flèche canonique

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:base-change-comparison-over-a-prime}{}%
\IllusiePoneFortyOneDisplay{L_{B/A}\otimes_B B_1\longrightarrow L_{B_1/A'}
\quad (\text{resp. }(L_{B/A}\otimes_B B_1)\oplus(B_1\otimes_{A'}L_{A'/A})
\longrightarrow L_{B_1/A})}

\vspace{5bp}
\noindent est un quasi-isomorphisme. Par Künneth (I 3.3.2), il en résulte que

\vspace{0.6bp}
\phantomsection\hypertarget{illusie:I:ch1:p141:tensor-composed-comparison}{}%
\IllusiePoneFortyOneDisplay{L_{B/A}\otimes_B B'\longrightarrow
L_{B_1/A'}\otimes_{B_1}B'\quad
(\text{resp. }(L_{B/A}\otimes_B B')\oplus(B'\otimes_{A'}L_{A'/A})
