\phantomsection\hypertarget{illusie:I:ch1:p142:proposition-2.3.0-cont}{}%
\noindent \uline{annelés}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:localization-topoi-square-2.3.0}{}%
\noindent\makebox[\dimexpr\linewidth-30.4bp\relax][c]{\IllusieLocalizationTopoiSquarePOneFortyTwo}\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:localization-cotangent-isomorphism}{}%
\noindent \uline{où les flèches horizontales sont les flèches de localisation},\quad $f'$ \uline{étant induit}\par
\noindent \uline{par}\quad $F$ . \uline{Alors ia flèche canonique}\quad $u^*L_{X/Y}\longrightarrow L_{X'/Y'}$ \uline{est un isomorphisme}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:proof-2.3.0}{}%
\noindent \uline{Preuve}. \phantomsection\hypertarget{illusie:I:ch1:p142:inverse-image-structure-ring-identification}{}%
La flèche $f'^{-1}(\underline{\mathrm{O}}_{Y'})\longrightarrow\underline{\mathrm{O}}_{X'}$ s'identifie à l'image par $u^{-1}$ de la flèche\par
\noindent $f^{-1}(\underline{\mathrm{O}}_Y)\longrightarrow\underline{\mathrm{O}}_X$ ,\quad donc l'assertion résulte de (1.2.3.5).

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:proposition-2.3.1}{}%
\noindent \uline{Proposition} 2.3.1.\quad \uline{Soient}\quad $T$ \uline{un topos},\quad $u:A\longrightarrow B$ \uline{un morphisme d'Anneaux de}\quad $T$ .\par
\phantomsection\hypertarget{illusie:I:ch1:p142:ring-epimorphism-flatness-hypotheses}{}%
\noindent \uline{On suppose que}\quad $u$ \uline{est un épimorphisme dans la catégorie des Anneaux de}\quad $T$ (\uline{i.e.}\par
\noindent \uline{que la flèche produit}\quad $B\otimes_A B\longrightarrow B$ \uline{est un isomorphisme}), \uline{et que}\quad $B$ \uline{est plat sur}\quad $A$.\par
\phantomsection\hypertarget{illusie:I:ch1:p142:cotangent-vanishing}{}%
\noindent \uline{Alors on a}\quad $L_{B/A}=0$ \uline{dans}\quad $D(B)$.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:proof-2.3.1}{}%
\noindent \uline{Preuve}. Par hypothèse, le carré ci-dessous est cocartésien :

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:cocartesian-ring-square-2.3.1}{}%
\noindent\makebox[\dimexpr\linewidth-24.4bp\relax][c]{\IllusieRingEpimorphismPushoutSquarePOneFortyTwo}\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:flat-base-change-comparison}{}%
\noindent Comme $B$ est plat sur $A$ , il résulte de (2.2.1) que $L_{B/A}\longrightarrow L_{B/B}$ est un\par
\noindent quasi-isomorphisme. Mais $L_{B/B}=0$ dans $D(B)$ d'après (1.2.4.4) (puisque $\Omega^1_{B/B}=0$),\par
\phantomsection\hypertarget{illusie:I:ch1:p142:proof-2.3.1-conclusion}{}%
\noindent d'où l'assertion.

