\noindent\makebox[\dimexpr\linewidth-30.4bp\relax][c]{\IllusieLocalizationTopoiSquarePOneFortyTwo}\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:localization-cotangent-isomorphism}{}%
\noindent \uline{where the horizontal arrows are the localization morphisms},\quad $f'$ \uline{being induced}\par
\noindent \uline{by}\quad $f$. \uline{Then the canonical map}\quad $u^*L_{X/Y}\longrightarrow L_{X'/Y'}$ \uline{is an isomorphism}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:proof-2.3.0}{}%
\noindent \uline{Proof}. \phantomsection\hypertarget{illusie:I:ch1:p142:inverse-image-structure-ring-identification}{}%
The map $f'^{-1}(\mathcal O_{Y'})\longrightarrow\mathcal O_{X'}$ identifies with the inverse image under $u^{-1}$ of the map\par
\noindent $f^{-1}(\mathcal O_Y)\longrightarrow\mathcal O_X$; hence the assertion follows from (1.2.3.5).

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:proposition-2.3.1}{}%
\noindent \uline{Proposition} 2.3.1.\quad \uline{Let}\quad $T$ \uline{be a topos},\quad and let $u:A\longrightarrow B$ \uline{be a morphism of rings on}\quad $T$.\par
\phantomsection\hypertarget{illusie:I:ch1:p142:ring-epimorphism-flatness-hypotheses}{}%
\noindent \uline{Suppose that}\quad $u$ \uline{is an epimorphism in the category of rings on}\quad $T$ (\uline{i.e.}\par
\noindent \uline{that the multiplication map}\quad $B\otimes_A B\longrightarrow B$ \uline{is an isomorphism}), \uline{and that}\quad $B$ \uline{is flat over}\quad $A$.\par
\phantomsection\hypertarget{illusie:I:ch1:p142:cotangent-vanishing}{}%
\noindent \uline{Then we have}\quad $L_{B/A}=0$ \uline{in}\quad $D(B)$.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:proof-2.3.1}{}%
\noindent \uline{Proof}. By hypothesis, the square below is cocartesian:

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p142:cocartesian-ring-square-2.3.1}{}%
\noindent\makebox[\dimexpr\linewidth-24.4bp\relax][c]{\IllusieRingEpimorphismPushoutSquarePOneFortyTwo}\par

\vspace{5bp}
