\begin{illusiebodypage}{illusie:I:ch1:p143}
\label{rf-source-143}


% BEGIN SOURCE tex/common/localization_corollary_square_p143.tex
% Native flat-localization square from LNM 239, physical p.161 / printed p.143.
\providecommand{\IllusieLocalizationCorollarySquarePOneFortyThree}{%
  \begin{tikzpicture}[baseline=(current bounding box.center),>=stealth]
    \path[use as bounding box] (-0.22,-0.18) rectangle (3.02,2.84);
    \node (B)  at (0,2.64) {$B$};
    \node (Bp) at (2.75,2.64) {$B'$};
    \node (A)  at (0,0) {$A$};
    \node (Ap) at (2.75,0) {$A'$};
    \draw[->] (B) -- (Bp);
    \draw[->] (A) -- (Ap);
    \draw[->] (A) -- (B);
    \draw[->] (Ap) -- (Bp);
  \end{tikzpicture}%
}

% END SOURCE tex/common/localization_corollary_square_p143.tex



\vspace{0.2bp}\ReflowBodyFont 


\phantomsection\hypertarget{illusie:I:ch1:p143:corollary-2.3.1.1}{}%
\noindent \uline{Corollaire} 2.3.1.1.\quad \uline{Soit}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p143:ring-square-2.3.1.1}{}%
\noindent\hspace{130.5bp}\IllusieLocalizationCorollarySquarePOneFortyThree\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p143:horizontal-epimorphism-flatness-hypotheses}{}%
\noindent \uline{un carré commutatif d'anneaux de}\quad $T$. \uline{On suppose que les flèches horizontales sont}\par
\noindent \uline{des épimorphismes dans la catégorie des anneaux et que}\quad $A'$ (resp. $B'$) \uline{est plat}\par
\noindent \uline{sur}\quad $A$ (resp. $B$). \uline{Alors la flèche canonique}\quad
\phantomsection\hypertarget{illusie:I:ch1:p143:cotangent-base-change-quasi-isomorphism}{}%
$L_{B/A}\otimes_B B'\longrightarrow L_{B'/A'}$ \uline{est un}\par
\noindent \uline{quasi-isomorphisme}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p143:proof-2.3.1.1}{}%
\noindent \uline{Preuve}. D'après (2.3.1) on a
\phantomsection\hypertarget{illusie:I:ch1:p143:localization-cotangent-vanishings}{}%
$L_{A'/A}$ (resp. $L_{B'/B}$) $=0$ dans $D(A')$ (resp. $D(B'))$.\par
\phantomsection\hypertarget{illusie:I:ch1:p143:transitivity-triangle-conclusion}{}%
\noindent L'assertion résulte donc des triangles de transitivité relatifs à $A\longrightarrow B\longrightarrow B'$\par
\noindent et $A\longrightarrow A'\longrightarrow B'$.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p143:criterion-2.3.2}{}%
\noindent 2.3.2.\quad Les hypothèses de (2.3.1) sont vérifiées en particulier si $u$ est un\par
\phantomsection\hypertarget{illusie:I:ch1:p143:localization-morphism-definition}{}%
\noindent \uline{morphisme de localisation}, par quoi nous entendons qu'il existe un sous-faisceau\par
\noindent d'ensembles $X$ de $A$ tel que $u(X)$ soit contenu dans le sous-faisceau $B^*$ des\par
\noindent unités de $B$ et que la flèche canonique $X^{-1}A\longrightarrow B$ induite par $u$ soit un\par
\noindent isomorphisme (cf. ([17] 9.4.4)). \phantomsection\hypertarget{illusie:I:ch1:p143:fraction-ring-universal-property}{}%
(Rappelons que l'anneau de fractions $X^{-1}A$ et\par
\noindent la flèche canonique $A\longrightarrow X^{-1}A$ sont caractérisés par la propriété universelle\par
\noindent habituelle, à savoir que toute flèche de $A$ dans un anneau $A'$ envoyant $X$ dans\par
\noindent $A'{}^*$ se factorise de manière unique à travers $X^{-1}A$). \phantomsection\hypertarget{illusie:I:ch1:p143:maximal-localizing-subsheaf}{}%
Noter que si $u$ est un\par
\vspace{4.7bp}
\noindent morphisme de localisation, il existe un plus grand $X$ possédant la propriété\par
\noindent indiquée plus haut, à savoir $u^{-1}(B^*)$. \phantomsection\hypertarget{illusie:I:ch1:p143:localization-epimorphism-flatness}{}%
Le fait qu'un morphisme de localisation\par
\vspace{1.5bp}
\noindent soit un épimorphisme dans la catégorie des anneaux est trivial sur la définition,\par
\noindent quant au fait que $X^{-1}A$ soit plat sur $A$, il se vérifie facilement tout comme\par
\vspace{1.5bp}
\noindent dans le cas des anneaux ordinaires.

