\phantomsection\hypertarget{illusie:I:ch1:p144:lemma-2.3.3}{}%
\noindent \uline{Lemme} 2.3.3.\quad \phantomsection\hypertarget{illusie:I:ch1:p144:lemma-2.3.3-i}{}%
(i)\quad \uline{Soit}\quad $u:A\longrightarrow B$ \uline{un morphisme de}\quad préfaisceaux \uline{d'anneaux de}\quad $T$.\par
\noindent \uline{Si}, \uline{pour tout}\quad $U\in\operatorname{ob}T$,\quad $u(U):A(U)\longrightarrow B(U)$ \uline{est un morphisme de localisation},\par
\phantomsection\hypertarget{illusie:I:ch1:p144:associated-sheaf-localization}{}%
\noindent \uline{alors le morphisme de faisceaux d'anneaux associé}\quad $\underline a u:\underline a A\longrightarrow\underline a B$ \uline{est un morphisme}\par
\noindent \uline{de localisation}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p144:lemma-2.3.3-ii}{}%
\noindent\hspace{39bp}(ii)\quad \uline{Soit}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p144:localization-base-change-triangle}{}%
\noindent\hspace{151bp}\IllusieLocalizationBaseChangeTrianglePOneFortyFour\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p144:localization-base-change}{}%
\noindent \uline{un diagramme commutatif d'anneaux de}\quad $T$. \uline{Si}\quad $u$ \uline{est de localisation}, \uline{alors pour}\par
\noindent \uline{toute}\quad $C$-\uline{algèbre}\quad $C'$,\quad $u\otimes_C C':A\otimes_C C'\longrightarrow B\otimes_C C'$ \uline{est de localisation}.

\vspace{2.0bp}
\phantomsection\hypertarget{illusie:I:ch1:p144:lemma-2.3.3-iii}{}%
\noindent\hspace{39bp}(iii)\quad \uline{Soient}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p144:localization-composition-chain}{}%
\noindent\hspace{123bp}\IllusieLocalizationCompositionChainPOneFortyFour\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p144:localization-composition}{}%
\noindent \uline{des morphismes d'anneaux de}\quad $T$. \uline{Si}\quad $u$ \uline{et}\quad $v$ \uline{sont de localisation}, \uline{il en est de}\par
\noindent \uline{même de $vu$}. \uline{Inversement}, \uline{si}\quad $vu$ \uline{est de localisation et si}\quad $u$ \uline{est un épimorphisme}\par
\noindent \uline{de la catégorie des anneaux}, \uline{alors}\quad $v$ \uline{est de localisation}.

\phantomsection\hypertarget{illusie:I:ch1:p144:lemma-2.3.3-iv}{}%
\noindent\hspace{39bp}(iv)\quad \uline{Soit}\quad $f:T'\longrightarrow T$ \uline{un morphisme de topos}, \uline{et soit}\quad $u:A\longrightarrow B$ \uline{un}\par
