\noindent \uline{Corollaire} 2.3.5.\quad \uline{Soient}\quad $Y$ \uline{un topos annelé},\quad $X$ \uline{un schéma relatif sur}\quad $Y$ \uline{au sens}\par
\noindent \uline{de Mme Hakim} ([18]Chap. IV), \uline{d'où} (loc. cit.) \uline{des morphismes de topos annelés}\par
\noindent $X\longrightarrowY^{\sim}\xrightarrow{p}Y$ , \uline{où}\quad $Y^{\sim}$ \uline{est le spectre de}\quad $Y$ \uline{et}\quad $p$ \uline{la projection canonique}.\par
\phantomsection\hypertarget{illusie:I:ch1:p146:relative-spectrum-cotangent-quasi-isomorphism}{}%
\noindent \uline{La flèche canonique}\quad $L_{X/Y}\longrightarrow L_{X/Y^{\sim}}$ \uline{est un quasi-isomorphisme}.

