\noindent \uline{de Mme Hakim} ([18]Chap. IV), \uline{d'où} (loc. cit.) \uline{des morphismes de topos annelés}\par
\noindent $X\longrightarrow\widetilde Y\xrightarrow{p}Y$ , \uline{où}\quad $\widetilde Y$ \uline{est le spectre de}\quad $Y$ \uline{et}\quad $p$ \uline{la projection canonique}.\par
\phantomsection\hypertarget{illusie:I:ch1:p146:relative-spectrum-cotangent-quasi-isomorphism}{}%
\noindent \uline{La flèche canonique}\quad $L_{X/Y}\longrightarrow L_{X/\widetilde Y}$ \uline{est un quasi-isomorphisme}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:proof-2.3.5}{}%
\noindent \uline{Preuve}. D'après (2.3.4) et (2.3.1) on a
\phantomsection\hypertarget{illusie:I:ch1:p146:spectrum-cotangent-vanishing}{}%
$L_{\widetilde Y/Y}=0$ dans $D(\widetilde Y)$ . L'assertion\par
\phantomsection\hypertarget{illusie:I:ch1:p146:transitivity-triangle-conclusion-2.3.5}{}%
\noindent résulte donc du triangle de transitivité (2.1.5.6) relatif à $X\longrightarrow\widetilde Y\longrightarrow Y$ .

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:corollary-2.3.6}{}%
\noindent \uline{Corollaire} 2.3.6.\quad \uline{Soit}\quad $X$ \uline{un schéma affine d'anneau}\quad $A$ , \uline{notons}\quad $A_X$ \uline{le faisceau}\par
\noindent \uline{constant sur}\quad $X$ \uline{de valeur}\quad $A$ . \uline{Le morphisme canonique}\quad
\phantomsection\hypertarget{illusie:I:ch1:p146:constant-sheaf-localization}{}%
$A_X\longrightarrow\mathcal O_X$ (EGA Err I 1.8.4)\par
\noindent \uline{est un morphisme de localisation}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:proof-2.3.6}{}%
