\vspace{5bp}\ReflowBodyFont\IllusieUprightLatinMath


\phantomsection\hypertarget{illusie:I:ch1:p146:corollary-2.3.5}{}%
\noindent \uline{Corollary} 2.3.5.\quad \uline{Let}\quad $Y$ \uline{be a ringed topos},\quad $X$ \uline{be a scheme relative to}\quad $Y$ \uline{in the sense}\par
\noindent \uline{of Mme Hakim} ([18]chap. IV), \uline{whence} (loc. cit.) \uline{morphisms of ringed topoi}\par
\noindent $X\longrightarrow\widetilde Y\xrightarrow{p}Y$, \uline{where}\quad $\widetilde Y$ \uline{is the spectrum of}\quad $Y$ \uline{and}\quad $p$ \uline{is the canonical projection}.\par
\phantomsection\hypertarget{illusie:I:ch1:p146:relative-spectrum-cotangent-quasi-isomorphism}{}%
\noindent \uline{The canonical map}\quad $L_{X/Y}\longrightarrow L_{X/\widetilde Y}$ \uline{is a quasi-isomorphism}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:proof-2.3.5}{}%
\noindent \uline{Proof}. By (2.3.4) and (2.3.1), one has
\phantomsection\hypertarget{illusie:I:ch1:p146:spectrum-cotangent-vanishing}{}%
$L_{\widetilde Y/Y}=0$ in $D(\widetilde Y)$. The assertion\par
\phantomsection\hypertarget{illusie:I:ch1:p146:transitivity-triangle-conclusion-2.3.5}{}%
\noindent therefore follows from the transitivity triangle (2.1.5.6) for $X\longrightarrow\widetilde Y\longrightarrow Y$.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:corollary-2.3.6}{}%
\noindent \uline{Corollary} 2.3.6.\quad \uline{Let}\quad $X$ \uline{be an affine scheme with ring}\quad $A$, \uline{and write}\quad $A_X$ \uline{for the constant sheaf}\par
\noindent \uline{on}\quad $X$ \uline{with value}\quad $A$. \uline{The canonical morphism}\quad
\phantomsection\hypertarget{illusie:I:ch1:p146:constant-sheaf-localization}{}%
$A_X\longrightarrow\mathcal O_X$ (EGA Err I 1.8.4)\par
\noindent \uline{is a localization morphism}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:proof-2.3.6}{}%
\noindent \uline{Proof}. Indeed, $X$ is the spectrum of the point topos ringed by $A$. One may also\par
\noindent note that $A_X\longrightarrow\mathcal O_X$ is trivially a localization morphism at every point, hence\par
\phantomsection\hypertarget{illusie:I:ch1:p146:pointwise-localization}{}%
\noindent a localization morphism by (2.3.3 (iv)).

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:s2.3.6-affine-scheme-comparison}{}%
\noindent 2.3.6.\quad Let $f:X\longrightarrow Y$ be a morphism of affine schemes corresponding to a\par
\noindent morphism of rings\quad $u:A\longrightarrow B$. Then there is a canonical commutative square

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:canonical-square-2.3.6.1}{}%
\noindent\IllusieAffineLocalizationSquarePOneFortySix\par

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:horizontal-localizations}{}%
\noindent where the horizontal morphisms are localization morphisms by (2.3.6)\quad (NB. the bottom morphism\par
\noindent is the inverse image under $f^{-1}$ of the canonical morphism $A_Y\longrightarrow\mathcal O_Y$, hence is a locali-\par
\noindent zation morphism by (2.3.3 (iv))). \phantomsection\hypertarget{illusie:I:ch1:p146:quasi-coherent-module-identification}{}%
Recall\quad (EGA Err I 1.8.5) that the functor assigning to\par
\noindent a $B$-module\quad $M$ the corresponding quasi-coherent $\mathcal O_X$-module $\widetilde M$ is canonically identified\par
\noindent with the functor\quad $M\longmapsto M_X\otimes_{B_X}\mathcal O_X$. \phantomsection\hypertarget{illusie:I:ch1:p146:cotangent-identification-leadin}{}%
In particular, canonically one has

