\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:proof-2.3.5}{}%
\noindent \uline{Proof}. By (2.3.4) and (2.3.1), one has
\phantomsection\hypertarget{illusie:I:ch1:p146:spectrum-cotangent-vanishing}{}%
$L_{\widetilde Y/Y}=0$ in $D(\widetilde Y)$. The assertion\par
\phantomsection\hypertarget{illusie:I:ch1:p146:transitivity-triangle-conclusion-2.3.5}{}%
\noindent therefore follows from the transitivity triangle (2.1.5.6) for $X\longrightarrow\widetilde Y\longrightarrow Y$.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p146:corollary-2.3.6}{}%
\noindent \uline{Corollary} 2.3.6.\quad \uline{Let}\quad $X$ \uline{be an affine scheme with ring}\quad $A$, \uline{and write}\quad $A_X$ \uline{for the constant sheaf}\par
\noindent \uline{on}\quad $X$ \uline{with value}\quad $A$. \uline{The canonical morphism}\quad
