\begin{illusiebodypage}{illusie:I:ch1:p147}
\label{rf-source-147}


% DÉBUT DU FICHIER SOURCE tex/common/ringed_topos_base_change_square_p147.tex
% Native base-change square from LNM 239, physical p.165 / printed p.147.
\providecommand{\IllusieRingedToposBaseChangeSquarePOneFortySeven}{%
  \begin{tikzpicture}[baseline=(current bounding box.center),>=stealth]
    \path[use as bounding box] (-0.55,-0.30) rectangle (4.05,2.45);
    \node (X) at (0,2.10) {$X$};
    \node (Xp) at (3.00,2.10) {$X'$};
    \node (S) at (0,0.21) {$S$};
    \node (Sp) at (3.00,0.21) {$S'$};
    \node[overlay,anchor=base west] at (4.20,0.21) {.};
    \draw[->] (Xp) -- node[above] {$u$} (X);
    \draw[->] (X) -- node[left] {$f$} (S);
    \draw[->] (Xp) -- node[right] {$f'$} (Sp);
    \draw[->] (Sp) -- node[above] {$v$} (S);
  \end{tikzpicture}%
}

% FIN DU FICHIER SOURCE tex/common/ringed_topos_base_change_square_p147.tex



\vspace{5bp}\ReflowBodyFont\IllusieUprightLatinMath


\phantomsection\hypertarget{illusie:I:ch1:p147:cotangent-identification-continuation}{}%

\ReflowDisplay{}{\kern-18.5bp
\begin{aligned}
(L_{B/A})^{\sim}&\xrightarrow{\sim}(L_{B/A})_X\otimes_{B_X}\mathcal O_X\\[26bp]
&\xrightarrow{\sim}L_{B_X/A_X}\otimes_{B_X}\mathcal O_X\qquad(1.2.1.4)\quad ,
\end{aligned}
\kern18.5bp}

\vspace{5bp}
\noindent et par suite le carré (2.3.6.1) fournit une flèche canonique


\phantomsection\hypertarget{illusie:I:ch1:p147:canonical-cotangent-map-2.3.6.2}{}%
\ReflowDisplay{}{\kern-22.4bp
\makebox[0pt][r]{\text{(2.3.6.2)}\hspace{106.7bp}}%
(L_{B/A})^{\sim}\longrightarrow L_{X/Y}\quad .
\kern22.4bp}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proposition-2.3.6.3}{}%
\noindent \uline{Proposition} 2.3.6.3.\quad \uline{La flèche}\quad (2.3.6.2) \uline{est un quasi-isomorphisme}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proof-2.3.6.3}{}%
\noindent \uline{Preuve}. Les flèches horizontales étant de localisation, l'assertion résulte de\par
\noindent (2.3.1.1).

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:corollary-2.3.7}{}%
\noindent \uline{Corollaire} 2.3.7.\quad \uline{Soit}\quad $f:X\longrightarrow Y$ \uline{un morphisme de schémas}. \uline{Les faisceaux}\par
\phantomsection\hypertarget{illusie:I:ch1:p147:cotangent-homology-quasi-coherence}{}%
\noindent \uline{d'homologie de}\quad $L_{X/Y}$ \uline{sont quasi-cohérents}. \phantomsection\hypertarget{illusie:I:ch1:p147:cotangent-homology-coherence}{}%
\uline{Ils sont cohérents si}\quad $Y$ \uline{est localement}\par
\noindent \uline{noethérien et}\quad $f$ \uline{localement de type fini}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proof-2.3.7}{}%
\noindent \uline{Preuve}. La question étant locale d'après (2.3.0), on peut supposer $X$ et $Y$ affine.\par
\noindent La première assertion résulte donc trivialement de (2.3.6.3). La seconde en résulte\par
\noindent aussi, compte tenu de (1.2.6.3) et du fait que, d'après André ([1] 17.2 p.69),\par
\phantomsection\hypertarget{illusie:I:ch1:p147:andre-finite-free-resolution}{}%
\noindent toute algèbre de type fini $B$ sur un anneau noethérien $A$ admet une résolution\par
\noindent $P\longrightarrow B$ où $P$ est une $A$-algèbre simpliciale libre de type fini en chaque degré.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proposition-2.3.8}{}%
\noindent \uline{Proposition} 2.3.8.\quad \uline{Soient}\quad $S'\longrightarrow S$ \uline{un morphisme de topos annelés},\quad $X$ \uline{un schéma}\par
\noindent \uline{relatif sur}\quad $S$ ([18]chap. IV),\quad $X'$ \uline{le schéma relatif sur}\quad $S'$ \uline{déduit par changement}\par
\noindent \uline{de base}, \uline{d'où un carré commutatif}\textsuperscript{(1)} \uline{de topos annelés}

\vspace{0.6bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:base-change-square-2.3.8}{}%
\begin{center}\hspace*{-32.8bp}\IllusieRingedToposBaseChangeSquarePOneFortySeven\end{center}


\phantomsection\hypertarget{illusie:I:ch1:p147:footnote-2.3.8-two-cartesian}{}%
\noindent\rule{72bp}{0.35bp}\par
\vspace{2.0bp}\noindent\textsuperscript{(1)} et même 2-cartésien ( [18] III 3.1).

