\phantomsection\hypertarget{illusie:I:ch1:p147:cotangent-identification-continuation}{}%

\ReflowDisplay{}{\kern-18.5bp
\begin{aligned}
(L_{B/A})^{\sim}&\mathrel{\overset{\sim}{\rule[.45ex]{14bp}{.35bp}}}(L_{B/A})_X\otimes_{B_X}\underline{\mathrm{O}}_X\\[26bp]
&\mathrel{\overset{\sim}{\rule[.45ex]{14bp}{.35bp}}}L_{B_X/A_X}\otimes_{B_X}\underline{\mathrm{O}}_X\qquad(1.2.1.4)\quad ,
\end{aligned}
\kern18.5bp}

\vspace{5bp}
\noindent et par suite le carré (2.3.6.1) fournit une flèche canonique


\phantomsection\hypertarget{illusie:I:ch1:p147:canonical-cotangent-map-2.3.6.2}{}%
\ReflowDisplay{}{\kern-22.4bp
\makebox[0pt][r]{\text{(2.3.6.2)}\hspace{106.7bp}}%
(L_{B/A})^{\sim}\longrightarrow L_{X/Y}\quad .
\kern22.4bp}

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proposition-2.3.6.3}{}%
\noindent \uline{Proposition} 2.3.6.3.\quad \uline{La flèche}\quad (2.3.6.2) \uline{est un quasi-isomorphisme}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proof-2.3.6.3}{}%
\noindent \uline{Preuve}. Les flèches horizontales étant de localisation, l'assertion résulte de
(2.3.1.1).

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:corollary-2.3.7}{}%
\noindent \uline{Corollaire} 2.3.7.\quad \uline{Soit}\quad $f:X\longrightarrow Y$ \uline{un morphisme de schémas}. \uline{Les faisceaux}
\phantomsection\hypertarget{illusie:I:ch1:p147:cotangent-homology-quasi-coherence}{}%
\uline{d'homologie de}\quad $L_{X/Y}$ \uline{sont quasi-cohérents}. \phantomsection\hypertarget{illusie:I:ch1:p147:cotangent-homology-coherence}{}%
\uline{Ils sont cohérents si}\quad $Y$ \uline{est localement}
\uline{noethérien et}\quad $f$ \uline{localement de type fini}.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proof-2.3.7}{}%
\noindent \uline{Preuve}. La question étant locale d'après (2.3.0), on peut supposer $X$ et $Y$ affine.
La première assertion résulte donc trivialement de (2.3.6.3). La seconde en résulte
aussi, compte tenu de (1.2.6.3) et du fait que, d'après André ([1] 17.2 p.69),
\phantomsection\hypertarget{illusie:I:ch1:p147:andre-finite-free-resolution}{}%
toute algèbre de type fini $B$ sur un anneau noethérien $A$ admet une résolution
$P\longrightarrow B$ où $P$ est une $A$-algèbre simpliciale libre de type fini en chaque degré.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proposition-2.3.8}{}%
\noindent \uline{Proposition} 2.3.8.\quad \uline{Soient}\quad $S'\longrightarrow S$ \uline{un morphisme de topos annelés},\quad $X$ \uline{un schéma}
\uline{relatif sur}\quad $S$ ([18]chap. IV),\quad $X'$ \uline{le schéma relatif sur}\quad $S'$ \uline{déduit par changement}
\uline{de base}, \uline{d'où un carré commutatif}(\textsuperscript{1}) \uline{de topos annelés}

\vspace{0.6bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:base-change-square-2.3.8}{}%
\begin{center}\hspace*{-32.8bp}\IllusieRingedToposBaseChangeSquarePOneFortySeven\end{center}


