\phantomsection\hypertarget{illusie:I:ch1:p147:proof-2.3.7}{}%
\noindent \uline{Preuve}. La question étant locale d'après (2.3.0), on peut supposer $X$ et $Y$ affines.\par
\noindent La première assertion résulte donc trivialement de (2.3.6.3). La seconde en résulte\par
\noindent aussi, compte tenu de (1.2.6.3) et du fait que, d'après André ([1] 17.2 p.69),\par
\phantomsection\hypertarget{illusie:I:ch1:p147:andre-finite-free-resolution}{}%
\noindent toute algèbre de type fini $B$ sur un anneau noethérien $A$ admet une résolution\par
\noindent $P\longrightarrow B$ où $P$ est une $A$-algèbre simpliciale libre de type fini en chaque degré.

\vspace{5bp}
\phantomsection\hypertarget{illusie:I:ch1:p147:proposition-2.3.8}{}%
\noindent \uline{Proposition} 2.3.8.\quad \uline{Soient}\quad $S'\longrightarrow S$ \uline{un morphisme de topos annelés},\quad $X$ \uline{un schéma}\par
\noindent \uline{relatif sur}\quad $S$ ([18]chap. IV),\quad $X'$ \uline{le schéma relatif sur}\quad $S'$ \uline{déduit par changement}\par
\noindent \uline{de base}, \uline{d'où un carré commutatif}\textsuperscript{(1)} \uline{de topos annelés}

