    \node (TR) at (2.61,2.90) {$f'^{-1}A'$};
    \node (BL) at (-2.61,0)
      {$u^{-1}\mathcal O_X\otimes_{h^{-1}\mathcal O_S}f'^{-1}\mathcal O_{S'}$};
    \node (BR) at (2.61,0) {$\mathcal O_{X'}$};
