% DÉBUT DU FICHIER SOURCE tex/common/stalkwise_tor_comparisons_p150.tex
% Native formula rows from LNM 239, physical p.168 / printed p.150.
% The second row intentionally preserves the source's omitted tensor base.
\providecommand{\IllusieStalkwiseRelativeTorComparisonPOneFifty}{%
  \ensuremath{\operatorname{Tor}_i^{h^{-1}(\mathcal O_S)}
    \bigl(p^{-1}(\mathcal O_X),\hspace{6bp}q^{-1}(\mathcal O_Y)\bigr)_z
    \hspace{6bp}\simeq\hspace{6bp}
    \operatorname{Tor}_i^{\mathcal O_{S,s}}
    \bigl(\mathcal O_{X,x},\hspace{6bp}\mathcal O_{Y,y}\bigr)\hspace{18bp} ;}%
}

\providecommand{\IllusieSheafTorStalkLocalizationPOneFifty}{%
  \ensuremath{\mathcal T\!or_i^S(\mathcal O_X,\hspace{5bp}\mathcal O_Y)_z
    \hspace{4bp}\simeq\hspace{4bp}
    \operatorname{Tor}_i^{\mathcal O_{S,s}}
    \bigl(\mathcal O_{X,x},\hspace{5bp}\mathcal O_{Y,y}\bigr)
    \hspace{4bp}\otimes\hspace{4bp}\mathcal O_{Z,z}\hspace{13bp} ;}%
}

\providecommand{\IllusieAffineNeighborhoodTorLimitPOneFifty}{%
  \ensuremath{\operatorname{Tor}_i^{\mathcal O_{S,s}}
    \bigl(\mathcal O_{X,x},\hspace{5bp}\mathcal O_{Y,y}\bigr)
    \hspace{5bp}\simeq\hspace{5bp}
    \underset{\longrightarrow}{\lim}\hspace{4bp}
    \operatorname{Tor}_i^{\mathcal O_S(W)}
    \bigl(\mathcal O_X(U),\hspace{5bp}\mathcal O_Y(V)\bigr)\hspace{25bp} ,}%
}

% FIN DU FICHIER SOURCE tex/common/stalkwise_tor_comparisons_p150.tex


