    \draw[->] (Jb) -- (OCb);
    \draw[->] (OCb) -- (ZbR);

    \draw[->] (It) -- node[left=6.5bp] {$\operatorname{id}$} (Ib);
    \draw[->] (OBt) -- node[right=5.0bp] {$u$} (Jb);
    \draw[->] (OCt) -- node[right=6.0bp] {$\operatorname{id}$} (OCb);
    \node[anchor=base] at ([xshift=13bp]ZbR.base) {$,$};
