    \node (Xp) at (235,40) {$X'$};
    \node (Y) at (171,0) {$Y$};
    \draw[->] (X) -- node[above=1.2bp] {$i$} (Xp);
    \draw[->] (X) -- node[left=6.0bp] {$f$} (Y);
