% BEGIN SOURCE tex/common/fundamental_theorem_carriers_p162.tex
% Shared formula carriers and native diagram from LNM 239,
% physical p.180 / printed p.162.
\providecommand{\IllusieDerHomPOneSixtyTwo}{%
  $\operatorname{Der}_{f^{-1}(\underline{\mathrm{O}}_Y)}(\underline{\mathrm{O}}_X,I)
    \xrightarrow{\sim}
    \operatorname{Hom}_{\underline{\mathrm{O}}_X}(\Omega^1_{X/Y},I)$%
}

\providecommand{\IllusieFundamentalIsomorphismPOneSixtyTwo}{%
  $\operatorname{Exal}_A(B,M)
    \xrightarrow{\sim}
    \mathop{\mathbb E\mathrm{xt}}\nolimits^1_B(L_{B/A},M)$%
}

\providecommand{\IllusieStandardFreeResolutionPOneSixtyTwo}{%
  \begin{tikzpicture}[baseline=(current bounding box.center),>=stealth,x=1bp,y=1bp]
    \path[use as bounding box] (-3,-7) rectangle (73,61);
    \node (P) at (0,52) {$P$};
    \node (B) at (69,52) {$B$};
    \node (A) at (69,0) {$A$};
    \draw[->] (P) -- node[above=1.2bp] {$p$} (B);
    \draw[->] (A) -- (B);
    \draw[->] (A) -- (P);
  \end{tikzpicture}%
}

\providecommand{\IllusieCotangentIdentityPOneSixtyTwo}{%
  $L_{B/A}=\Omega^1_{P/A}\otimes_P B$%
}

\providecommand{\IllusieExtComparisonPOneSixtyTwo}{%
  $\mathop{\mathbb E\mathrm{xt}}\nolimits^1_P(\Omega^1_{P/A},M)
    \xrightarrow{\sim}
    \mathop{\mathbb E\mathrm{xt}}\nolimits^1_B(L_{B/A},M)$%
}

\providecommand{\IllusieFootnoteExtComparisonPOneSixtyTwo}{%
  $\mathop{\mathbb E\mathrm{xt}}\nolimits^n_B(L,M)
    \simeq \mathop{\mathbb E\mathrm{xt}}\nolimits^n_B(L^{\sim},M)
    \simeq H^n\operatorname{RHom}_B(L^{\sim},M)$%
}

% END SOURCE tex/common/fundamental_theorem_carriers_p162.tex


\ReflowBodyFont\IllusieUprightLatinMath



\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:1:10:classes}{}%
in the evident way. The set of isomorphism classes of $Y$-extensions of $X$\par

\noindent\makebox[0pt][l]{by an $\underline{\mathrm{O}}_X$-module $I$ (i.e. diagrams (1.1.10.1) such that $\operatorname{Ker}(i^{-1}(\underline{\mathrm{O}}_{X'})\longrightarrow\underline{\mathrm{O}}_X)\simeq I$)}\par
is naturally identified with $\operatorname{Exal}_{f^{-1}(\underline{\mathrm{O}}_Y)}(\underline{\mathrm{O}}_X,I)$. The group of automorphisms of a 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:1:10:automorphisms}{}%
given $Y$-extension of $X$ by $I$ is canonically identified with\par

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:1:10:Der-Hom}{}%
\noindent\IllusieDerHomPOneSixtyTwo\hspace*{13.0bp}(cf. (1.1.5) and (II 1.1.4)).\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:heading}{}
\ReflowDestination{rf-toc-033}{2}{1.2. The fundamental theorem}
%
\noindent 1.2.\quad \uline{The fundamental theorem}.\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:0:para}{}%
1.2.0.\quad Let $T$ be a topos, $A\longrightarrow B$ a morphism of rings on $T$, and $M$ a B-module. 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:0:goal}{}%
The aim of section (1.2) is to establish a functorial isomorphism\par


\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:0:isomorphism}{}%
\noindent\hspace*{110.0bp}\IllusieFundamentalIsomorphismPOneSixtyTwo\hspace*{18.0bp}.\hspace*{22.0bp}\textsuperscript{(1)}\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:para}{}%
\noindent 1.2.1.\quad Let\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:resolution:diagram}{}%
\noindent\hspace*{143.0bp}\IllusieStandardFreeResolutionPOneSixtyTwo\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:resolution:prose}{}%
the standard free resolution of $B$ over $A$ (I 1.5.5.6). Recall that by defini-\par

\noindent tion (II 1.2.3)\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:cotangent}{}%
\noindent\hspace*{129.0bp}\IllusieCotangentIdentityPOneSixtyTwo\hspace*{18.0bp},\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:flatness}{}%
and $\Omega^1_{P/A}$ is a flat P-module. By (I 3.3.4.4), there is therefore an isomorphism\par

\noindent which is canonical\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:eq1}{}%
\noindent\makebox[0pt][l]{(1.2.1.1)}\hspace*{98.0bp}\IllusieExtComparisonPOneSixtyTwo\hspace*{17.0bp}.\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:0:isomorphism:n1}{}%
\noindent\hspace*{-5.5bp}\rule{72.6bp}{0.4bp}\par
\ReflowBodyFont\IllusieUprightLatinMath
\noindent\makebox[0pt][l]{\hspace*{-5.0bp}\textsuperscript{(1)} Recall (I 3.2.1.15) that if $L$ is a simplicial B-module and $L^{\sim}$ denotes}\par
the corresponding chain complex, there are canonical isomorphisms\par

\noindent\hspace*{71.0bp}\IllusieFootnoteExtComparisonPOneSixtyTwo\hspace*{15.0bp}.\par

