\noindent\makebox[0pt][l]{(1.2.1.2)}%
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:eq2:commutative-square}{}%
\hspace*{155.0bp}\IllusieBaseChangeSquarePOneSixtyThree\par

\vspace{5bp}
un carré commutatif d'Anneaux, d'où (II 1.2.1.2) un diagramme commutatif.\par


\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:eq3}{}%
\noindent\makebox[0pt][l]{(1.2.1.3)}%
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:1:eq3:P-prime}{}%
\hspace*{137.0bp}\IllusieResolutionBaseChangeDiagramPOneSixtyThree\par

\vspace{5bp}
