% DÉBUT DU FICHIER SOURCE tex/common/fundamental_theorem_inverse_p167.tex
% Shared formula carriers and native morphism-of-extensions diagram from
% LNM 239, physical p.185 / printed p.167.
% Seven carriers preserve nine displayed rows.  All mathematical witnesses
% are common to the diplomatic French, corrected French, and English lanes.
\providecommand{\IllusieFundamentalInverseMorphismPOneSixtySeven}{%
  \begin{tikzpicture}[baseline=(current bounding box.center),>=stealth,x=1bp,y=1bp]
    \path[use as bounding box] (0,-5) rectangle (307,63);
    \node[anchor=west] (AT) at (0,58) {$\operatorname{alg}(Y)$};
    \node (Tz) at (92,58) {$0$};
    \node (TN) at (137,58) {$N$};
    \node (TE) at (195,58) {$E$};
    \node (TP) at (252,58) {$P$};
    \node (To) at (302,58) {$0$};
    \node[anchor=west] (AB) at (0,0) {$H_0\operatorname{alg}(Y)$};
    \node (Bz) at (92,0) {$0$};
    \node (BN) at (137,0) {$H_0N$};
    \node (BE) at (195,0) {$H_0E$};
    \node (BP) at (252,0) {$H_0P$};
    \node (Bo) at (302,0) {$0$};
    \draw[->] (Tz) -- (TN);
    \draw[->] (TN) -- (TE);
    \draw[->] (TE) -- (TP);
    \draw[->] (TP) -- (To);
    \draw[->] (Bz) -- (BN);
    \draw[->] (BN) -- (BE);
    \draw[->] (BE) -- (BP);
    \draw[->] (BP) -- (Bo);
    \draw[->] (TN) -- node[left=1.8bp] {$v$} (BN);
    \draw[->] (TE) -- (BE);
    \draw[->] (TP) -- node[right=1.8bp] {$(H_0p)^{-1}p$} (BP);
  \end{tikzpicture}%
}

\providecommand{\IllusieFundamentalInverseProjectionRelationPOneSixtySeven}{%
  $H_0\operatorname{alg}(Y)*(H_0p)^{-1}*P
    =v*\operatorname{alg}(Y)\quad .$%
}

\providecommand{\IllusieFundamentalInverseChiComparisonPOneSixtySeven}{%
  $\begin{aligned}
    \alpha\beta(y)
      &=\sigma\bigl((H_0s^{-1})v\bigr)\chi\bigl(\operatorname{diff}\operatorname{alg}(Y)\bigr)\\
      &=\sigma\bigl((H_0s^{-1})v\bigr)\chi(Y)
        \hspace{78.0bp}(1.1.9)\quad .
  \end{aligned}$%
}

\providecommand{\IllusieFundamentalInverseHZeroSPOneSixtySeven}{%
  $vs=H_0s\quad ,$%
}

\providecommand{\IllusieFundamentalInverseDerivedInversePOneSixtySeven}{%
  $(H_0s^{-1})v=s^{-1}\quad\text{dans }D_{\bullet}(P)\quad ,$%
}

\providecommand{\IllusieFundamentalInverseFinalPOneSixtySeven}{%
  $\alpha\beta(y)=\sigma s^{-1}\chi(Y)=y\quad ,$%
}

\providecommand{\IllusieModuleExactSequencePOneSixtySeven}{%
  $0\longrightarrow M'\longrightarrow M\xrightarrow{f}M''\longrightarrow0$%
}

% FIN DU FICHIER SOURCE tex/common/fundamental_theorem_inverse_p167.tex


