      {$\operatorname{Ext}^1_Q(\Omega^1_{Q/P},M)$};
    \node[anchor=west] (BL) at (0,9) {$\operatorname{Der}_A(P,M)$};
    \node[anchor=west] (BR) at (170,9) {$\operatorname{Exal}_P(Q,M)$};
    \draw[->] (TL) -- (TR);
    \draw[->] ([xshift=30bp]TL.south west) -- ([xshift=30bp]BL.north west);
    \draw[->] ([xshift=31bp]TR.south west) -- node[right=8bp] {$\operatorname{alg}$} ([xshift=31bp]BR.north west);
    \draw[->] (BL) -- node[above=1.4bp] {$\partial$} (BR);
