  \scalebox{1.095}[1]{$\displaystyle
    \operatorname{Hom}_B(I/I^2,M)
    \xrightarrow{\sim}
    \operatorname{Exal}_A(B,M)$}%
}

\providecommand{\IllusieSurjectionHOnePOneSeventyFive}[1]{%
  \scalebox{1.08}[1]{$\displaystyle
    H_1(L_{B/A})\xrightarrow{\sim}I/I^2#1$}%
}

\providecommand{\IllusieSurjectionHomExtPOneSeventyFive}{%
  \scalebox{1.065}[1]{$\displaystyle
    \operatorname{Hom}_B(H_1(L_{B/A}),M)
