}

% FIN DU FICHIER SOURCE tex/common/surjection_extensions_p175.tex


\ReflowBodyFont\IllusieUprightLatinMath



\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:lemma}{}%
\uline{Lemme} 1.2.8.\quad \uline{Soit} $A\longrightarrow B$ \uline{un morphisme d'Anneaux}, \uline{surjectif de noyau} $I$\hspace{3.0bp}. \uline{Notons}\par

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:extension}{}%
\noindent $U$\hspace{10.0bp}\uline{la A-extension}
\par

\vspace{5bp}
\noindent\hspace*{105.0bp}\IllusieSurjectionExtensionSequencePOneSeventyFive{\hspace{3.0bp}.}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:functorial-isomorphism}{}%
\uline{Alors}\quad $f\longmapsto f{*}U$\quad \uline{définit un isomorphisme fonctoriel}\par


\vspace{5bp}
\noindent\hspace*{119.0bp}\IllusieSurjectionHomExalPOneSeventyFive
\par

\vspace{5bp}
\uline{pour}\quad $M\in\operatorname{ob} B\text{-Mod}$.\par


\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:proof}{}%
\uline{Preuve}.\quad Recopier, mutatis mutandis, la démonstration de (EGA $0_{\mathrm{IV}}$ 18.3.8).\par


\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:1:corollary}{}%
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:1:h0-vanishing}{}%
\uline{Corollaire} 1.2.8.1.\quad \uline{Sous les hypothèses de} (1.2.8), \uline{on a} $H_0(L_{B/A})=0$\hspace{3.0bp}, \uline{et un}\par

\noindent\uline{isomorphisme fonctoriel canonique}
\par

\vspace{1.6bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:1:h1-isomorphism}{}%
\noindent\hspace*{161.0bp}\IllusieSurjectionHOnePOneSeventyFive{\hspace{3.0bp}.}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:1:proof}{}%
\uline{Preuve}.\quad Le produit $B\otimes_A B\longrightarrow B$ étant un isomorphisme, on a (II 1.1.2) $\Omega^1_{B/A}=0$\hspace{3.0bp}, 
donc (II 1.2.4.2) $H_0(L_{B/A})=0$\hspace{3.0bp}. Par suite, la projection canonique 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:1:projection}{}%
$L_{B/A}\longrightarrow H_1(L_{B/A})[1]$ définit un isomorphisme fonctoriel\par


\vspace{1.8bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:1:hom-ext}{}%
\noindent\hspace*{109.0bp}\IllusieSurjectionHomExtPOneSeventyFive
\par

\vspace{5bp}
pour $M\in\operatorname{ob} B\text{-Mod}$. Compte tenu de (1.2.3) et (1.2.8), on en déduit un isomorphisme\par

\noindent fonctoriel
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:8:1:hom-comparison}{}%
\noindent\hspace*{109.0bp}\IllusieSurjectionHomComparisonPOneSeventyFive{\hspace{3.0bp},}
\par

\vspace{5bp}
\noindent d'où la seconde assertion.
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:proposition}{}%
\uline{Proposition} 1.2.9.\quad \uline{Soient des morphismes d'Anneaux}\par

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:ring-morphisms}{}%
\noindent\makebox[0pt][l]{(*)}\hspace*{108.0bp}\IllusieSurjectionRingMorphismsPOneSeventyFive{\hspace{3.0bp},}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:square:lead}{}%
\uline{où}\quad $p$\quad \uline{est surjectif de noyau} $I$\hspace{3.0bp}. \uline{On a alors un carré commutatif}\par

