\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:proof:extension-diagram}{}%
\noindent\hspace*{69.0bp}%
\IllusieTransitivityExtensionDiagramPOneSeventySix{\hspace{3.0bp}.}
