% Shared native carriers from LNM 239, physical p.195 / printed p.177.
% Five structured linear formula carriers and two directed triangle diagrams
% are common to all three lanes.  Terminal punctuation is supplied lane by
% lane so that the diplomatic spacing witnesses remain reversible.

\providecommand{\IllusieCorollaryCanonicalMapPOneSeventySeven}{%
  \scalebox{1.14}[1]{$\displaystyle
    L_{P/A}\xrightarrow{\hspace{24bp}}\Omega^1_{P/A}$}%
}

\providecommand{\IllusieCorollaryChainPOneSeventySeven}[1]{%
  \scalebox{1.18}[1]{$\displaystyle
    0\longrightarrow I/I^2
    \xrightarrow{d_{P/A}}
    \Omega^1_{P/A}\otimes_P B
    \longrightarrow 0#1$}%
}

\providecommand{\IllusieCorollaryTransitivityTrianglePOneSeventySeven}[1]{%
  \begin{tikzpicture}[baseline=(lowerleft.base),>=stealth,x=1bp,y=1bp,
    every node/.style={inner sep=0pt,outer sep=0pt}]
    \path[use as bounding box] (0,-7) rectangle (272,102);
    \node (top) at (137,92) {$L_{B/P}$};
    \node (lowerleft) at (48,4) {$\Omega^1_{P/A}\otimes_P B$};
    \node (lowerright) at (225,4) {$L_{B/A}$};
    \draw[->] ([xshift=-5bp,yshift=-3bp]top.south west) --
      ([xshift=5bp,yshift=5bp]lowerleft.north east);
    \draw[->] ([xshift=6bp]lowerleft.east) -- ([xshift=-6bp]lowerright.west);
    \draw[->] ([xshift=-3bp,yshift=5bp]lowerright.north west) --
      ([xshift=5bp,yshift=-3bp]top.south east);
    \node[anchor=base] at ([xshift=28bp]lowerright.base east) {#1};
  \end{tikzpicture}%
}

\providecommand{\IllusieCorollaryTruncatedTrianglePOneSeventySeven}[1]{%
  \begin{tikzpicture}[baseline=(lowerleft.base),>=stealth,x=1bp,y=1bp,
    every node/.style={inner sep=0pt,outer sep=0pt}]
    \path[use as bounding box] (0,-7) rectangle (288,102);
    \node (top) at (141,92) {$I/I^2[1]$};
    \node (lowerleft) at (48,4) {$\Omega^1_{P/A}\otimes_P B$};
    \node (lowerright) at (235,4) {$t_{[-1}L_{B/A}$};
    \draw[->] ([xshift=-7bp,yshift=-3bp]top.south west) --
      ([xshift=5bp,yshift=5bp]lowerleft.north east);
    \draw[->] ([xshift=6bp]lowerleft.east) -- ([xshift=-6bp]lowerright.west);
    \draw[->] ([xshift=-4bp,yshift=5bp]lowerright.north west) --
      ([xshift=7bp,yshift=-3bp]top.south east);
    \node[anchor=base] at ([xshift=20bp]lowerright.base east) {#1};
  \end{tikzpicture}%
}

\providecommand{\IllusieCorollaryDegreeOneMapPOneSeventySeven}[1]{%
  \scalebox{1.04}[1]{$\displaystyle
    -d_{P/A}:I/I^2\longrightarrow\Omega^1_{P/A}\otimes_P B#1$}%
}

\providecommand{\IllusieCorollaryConeMapPOneSeventySeven}[1]{%
  \scalebox{1.04}[1]{$\displaystyle
    -d_{P/A}:I/I^2\longrightarrow\Omega^1_{P/A}\otimes_P B#1$}%
}

\providecommand{\IllusieCorollarySignComplexPOneSeventySeven}{%
  \scalebox{1.08}[1]{$\displaystyle
    0\longrightarrow I/I^2\longrightarrow
    \Omega^1_{P/A}\otimes_P B\longrightarrow0$}%
}

% FIN DU FICHIER SOURCE tex/common/truncation_corollary_p177.tex


\ReflowBodyFont\IllusieUprightLatinMath



\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:corollary}{}%
\uline{Corollaire} 1.2.9.1.\quad \uline{Sous les hypothèses de} (1.2.9), \uline{supposons que la flèche canonique} 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:canonical-map}{}%
\IllusieCorollaryCanonicalMapPOneSeventySeven\quad (II 1.2.4.1)\quad \uline{soit un quasi-isomorphisme et que}\quad $\Omega^1_{P/A}$\quad \uline{soit plat} 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:flatness}{}%
\uline{sur}\quad $P$\quad (\uline{ces deux conditions sont vérifiées par exemple si}\quad $P=S_A(M)$\hspace{3.0bp},\quad \uline{où}\quad $M$\quad \uline{est} 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:flat-example}{}%
\uline{un} $A$-\uline{Module plat}\quad (II 1.2.4.4))\hspace{3.0bp}. \uline{Alors dans}\quad $D(B)$, \uline{le tronqué à l'ordre un}\quad $t_{[-1}L_{B/A}$ 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:truncation}{}%
(I 1.4.7)\hspace{3bp}(\textsuperscript{1}) \uline{s'identifie au complexe de chaînes}\par


\vspace{3.0bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:chain-complex}{}%
\noindent\hspace*{93.0bp}\IllusieCorollaryChainPOneSeventySeven{\hspace{3.0bp},}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:degree-zero}{}%
\uline{où}\quad $\Omega^1_{P/A}\otimes_P B$\quad \uline{est placé en degré zéro}.\par


\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:proof}{}%
\uline{Preuve}.\quad Vu les hypothèses, le triangle de transitivité relatif à\quad $A\longrightarrow P\longrightarrow B$ (II 2.1.2.1) s'écrit
\par

\vspace{2.0bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:proof:transitivity-triangle}{}%
\noindent\hspace*{57.0bp}\IllusieCorollaryTransitivityTrianglePOneSeventySeven{\hspace{3.0bp}.}
\par

\vspace{5bp}
Par troncature on en déduit, compte tenu de (1.2.8.1) et (1.2.9), un triangle distingué\par


\vspace{1.0bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:proof:truncated-triangle}{}%
\noindent\hspace*{53.0bp}\IllusieCorollaryTruncatedTrianglePOneSeventySeven{\hspace{3.0bp},}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:proof:degree-one-map}{}%
où la flèche de degré un est donnée par\quad \IllusieCorollaryDegreeOneMapPOneSeventySeven{\hspace{3.0bp}.}\quad Par suite 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:proof:cone}{}%
$t_{[-1}L_{B/A}$ s'identifie dans $D(B)$ au cône de\quad \IllusieCorollaryConeMapPOneSeventySeven{\hspace{3.0bp},}\quad d'où 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:proof:sign-comparison}{}%
l'assertion (les complexes\quad \IllusieCorollarySignComplexPOneSeventySeven\quad munis des différentielles 
$d_{P/A}$\quad et\quad $-d_{P/A}$ étant évidemment canoniquement isomorphes).\par



\vfill
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:truncation:n1}{}%
\noindent\hspace*{-2.0bp}\rule{66.0bp}{0.4bp}
\par
\ReflowBodyFont\IllusieUprightLatinMath
(\textsuperscript{1}) $L_{B/A}$ est regardé ici comme objet de\quad $D(B)$\quad via Dold-Puppe (I 1.4.6).\par

\clearpage

