\IllusieCorollaryCanonicalMapPOneSeventySeven\quad (II 1.2.4.1)\quad \uline{soit un quasi-isomorphisme et que}\quad $\Omega^1_{P/A}$\quad \uline{soit plat} 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:flatness}{}%
\uline{sur}\quad $P$\quad (\uline{ces deux conditions sont vérifiées par exemple si}\quad $P=S_A(M)$\hspace{3.0bp},\quad \uline{où}\quad $M$\quad \uline{est} 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:flat-example}{}%
\uline{un} $A$-\uline{Module plat}\quad (II 1.2.4.4))\hspace{3.0bp}. \uline{Alors dans}\quad $D(B)$, \uline{le tronqué à l'ordre un}\quad $t_{[-1}L_{B/A}$ 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:truncation}{}%
(I 1.4.7)\hspace{3bp}(\textsuperscript{1}) \uline{s'identifie au complexe de chaînes}\par


\vspace{3.0bp}
