\noindent (II 2.1.2.1) is
\par

\vspace{2.0bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:2:9:1:proof:transitivity-triangle}{}%
\noindent\hspace*{57.0bp}\IllusieCorollaryTransitivityTrianglePOneSeventySeven{\hspace{3.0bp}.}
\par

\vspace{5bp}
