% BEGIN SOURCE tex/common/lemma_exactness_proposition_p180.tex
% Shared native carriers from LNM 239, physical p.198 / printed p.180.
% Five linear formula carriers and the Proposition 1.3.4 diagram are common
% to all three lanes.  Terminal punctuation is supplied lane by lane so that
% the diplomatic spacing witnesses remain reversible.

\providecommand{\IllusieLemmaKernelSequencePOneEighty}[1]{%
  \scalebox{1.429}[1]{$\displaystyle
    0\longrightarrow I\otimes_A P
    \longrightarrow J\longrightarrow K\longrightarrow 0#1$}%
}

\providecommand{\IllusieLemmaTensorSequencePOneEighty}[1]{%
  \scalebox{1.425}[1]{$\displaystyle
    I/I^2\longrightarrow J/J^2\longrightarrow K/K^2
    \longrightarrow 0#1$}%
}

\providecommand{\IllusieLemmaDifferentialsIsomorphismPOneEighty}[1]{%
  \scalebox{1.296}[1]{$\displaystyle
    \Omega^1_{P/A}\otimes_P Q
    \xrightarrow{\sim}\Omega^1_{Q/B}
    \qquad (\mathrm{II}\ 1.1.2.9)#1$}%
}

\providecommand{\IllusieLemmaConormalIsomorphismPOneEighty}[1]{%
  \scalebox{1.279}[1]{$\displaystyle
    K/K^2\xrightarrow{\sim}
    \Omega^1_{Q/B}\otimes_Q B#1$}%
}

\providecommand{\IllusieLemmaDerivedSequencePOneEighty}[1]{%
  \scalebox{1.314}[1]{$\displaystyle
    I/I^2\longrightarrow J/J^2\longrightarrow
    \Omega^1_{P/A}\otimes_P B\longrightarrow 0#1$}%
}

\providecommand{\IllusiePropositionDiagramPOneEighty}[1]{%
