      node[midway,xshift=-7bp] {$p$} ([xshift=-5bp,yshift=6bp]B.north west);
    \draw[->] ([xshift=-2bp,yshift=-5bp]Q.south) --
      node[midway,xshift=7bp] {$q$} ([xshift=5bp,yshift=6bp]B.north east);
    \node[anchor=west] at (265,4) {#1};
  \end{tikzpicture}%
}

