    0\longrightarrow\Omega^1_{P/A}\otimes_P B
    \longrightarrow\Omega^1_{Q/A}\otimes_Q B
    \longrightarrow\Omega^1_{Q/P}\otimes_Q B\longrightarrow 0#1$}%
}

