\uline{où} $P$ (resp. $Q$) \uline{est presque libre sur} $A$, \uline{et} $p$ (resp. $q$) \uline{surjectif}. \uline{Alors il existe}\par

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:isomorphism}{}%
\noindent \uline{un isomorphisme canonique de} $D(B)$
\par

\vspace{5bp}
\noindent\hspace*{154.0bp}\IllusieComparisonCanonicalIsomorphismPOneEightyTwo{.}
\par

\vspace{5bp}
