% BEGIN SOURCE tex/common/comparison_resolution_p182.tex
% Shared native carriers from LNM 239, physical p.200 / printed p.182.
% The Corollary 1.3.4.1 diamond and three single-row formula carriers are
% common to all three lanes. Terminal punctuation is supplied lane by lane
% so that the seven diplomatic spacing witnesses remain reversible.

\providecommand{\IllusieComparisonDiamondPOneEightyTwo}[1]{%
  \begin{tikzpicture}[baseline=(A.base),>=stealth,x=1bp,y=.835bp,
    every node/.style={inner sep=0pt,outer sep=0pt}]
    \path[use as bounding box] (0,-9.174) rectangle (215,127.353);
    \node (B) at (110,96) {$B$};
    \node (P) at (45,49) {$P$};
    \node (Q) at (175,49) {$Q$};
    \node (A) at (110,4) {$A$};
    \draw[->] ([xshift=-5bp,yshift=5bp]A.north west) --
      ([xshift=5bp,yshift=-5bp]P.south east);
    \draw[->] ([xshift=5bp,yshift=5bp]A.north east) --
      ([xshift=-5bp,yshift=-5bp]Q.south west);
    \draw[->] ([yshift=6bp]A.north) -- ([yshift=-6bp]B.south);
    \draw[->] ([xshift=5bp,yshift=5bp]P.north east) --
      node[above left,xshift=-1bp,yshift=1bp] {$p$}
      ([xshift=-5bp,yshift=-5bp]B.south west);
    \draw[->] ([xshift=-5bp,yshift=5bp]Q.north west) --
      node[above right,xshift=1bp,yshift=1bp] {$q$}
      ([xshift=5bp,yshift=-5bp]B.south east);
    \node[anchor=west] at (203,4) {#1};
  \end{tikzpicture}%
}

\providecommand{\IllusieComparisonCanonicalIsomorphismPOneEightyTwo}[1]{%
  \scalebox{1.12}[1]{$\displaystyle
    D_{B/P/A}\xrightarrow{\sim}D_{B/Q/A}#1$}%
}

\providecommand{\IllusieComparisonProofChainPOneEightyTwo}[1]{%
  \scalebox{1.14}[1]{$\displaystyle
    D_{B/P/A}\xrightarrow{\sim}D_{B/R/A}
    \xrightarrow{\sim}D_{B/Q/A}#1$}%
}

\providecommand{\IllusieResolutionCanonicalMapPOneEightyTwo}[1]{%
  \scalebox{1.08}[1]{$\displaystyle
    NL_{B/A}\longrightarrow D_{B/P_o/A}#1$}%
}

% END SOURCE tex/common/comparison_resolution_p182.tex


\vspace{1.88bp}\ReflowBodyFont 



\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:cor}{}%
\uline{Corollaire} 1.3.4.1\quad (cf. SGA 6 VIII 2.2).\quad \uline{Soit un diagramme commutatif d'Anneaux}\par



\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:diagram}{}%
\noindent\hspace*{70.0bp}\IllusieComparisonDiamondPOneEightyTwo{\hspace{3.0bp},}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:hypotheses}{}%
\uline{où} $P$ (resp. $Q$) \uline{est presque libre sur} $A$\hspace{3.0bp}, \uline{et} $p$ (resp. $q$) \uline{surjectif}. \uline{Alors il existe}\par

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:isomorphism}{}%
\noindent \uline{un isomorphisme canonique de} $D(B)$
\par

\vspace{5bp}
\noindent\hspace*{154.0bp}\IllusieComparisonCanonicalIsomorphismPOneEightyTwo{\hspace{3.0bp}.}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:proof}{}%
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:proof:tensor-product}{}%
\uline{Preuve}. La A-Algèbre $R=P\otimes_AQ$ est presque libre, donc, d'après (1.3.4) on a des\par

\noindent quasi-isomorphismes canoniques
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:proof:chain}{}%
\noindent\hspace*{112.0bp}\IllusieComparisonProofChainPOneEightyTwo{\hspace{3.0bp},}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:4:1:proof:conclusion}{}%
\noindent d'où l'assertion.
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:5:prop}{}%
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:5:data}{}%
\uline{Proposition} 1.3.5.\quad \uline{Soient} $A\longrightarrow B$ \uline{un morphisme d'Anneaux}, $P=P_A(B)$ \uline{la résolu-} 
\uline{tion libre standard de} $B$ \uline{sur} $A$\hspace{3.0bp}, $L_{B/A}=\Omega^1_{P/A}\otimes_PB$ \uline{le complexe cotangent} (II 1.2.3).\par

\noindent \uline{Il existe un morphisme canonique de complexes de B-Modules}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:5:map}{}%
\noindent\hspace*{149.0bp}\IllusieResolutionCanonicalMapPOneEightyTwo{\hspace{3.0bp},}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:5:homology}{}%
\noindent \uline{induisant des isomorphismes sur l'homologie en degré $\leq1$}\hspace{3.0bp}.\qquad\textsuperscript{(1)}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:5:conclusion}{}%
\noindent\hspace*{50.0bp}Conjuguant (1.3.5) et (1.3.4.1), on obtient le résultat annoncé au début
\par
\noindent de (1.3) :
\par


\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:5:n1}{}%
\noindent\rule{69.7bp}{0.4bp}
\par
\ReflowBodyFont 
\textsuperscript{(1)} N désigne le foncteur \textquotedbl complexe normal\textquotedbl\ (I 1.3.1) ; on rappelle d'autre part\par

\noindent que $P_o\longrightarrow B$ est surjectif.
\par
\vspace{5bp}

