% Shared native formula carriers from LNM 239, physical p.201 / printed p.183.
% Six linear carriers are common to all three lanes. Terminal punctuation is
% supplied lane by lane so that the twelve diplomatic witnesses are reversible.
% The lowercase letter o and the asymmetric truncation brackets are intentional.

\providecommand{\IllusieCorollaryDataChainPOneEightyThree}[1]{%
  \scalebox{1.665}[1]{$\displaystyle
    A\longrightarrow P\longrightarrow B#1$}%
}

\providecommand{\IllusieCorollaryNormalizedMapPOneEightyThree}{%
  \scalebox{1.165}[1]{$\displaystyle
    Nd_{P/A}:N(J/J^2)\longrightarrow NL_{B/A}$}%
}

\providecommand{\IllusieCorollaryUMapPOneEightyThree}[1]{%
  \scalebox{1.455}[1]{$\displaystyle
    u:NL_{B/A}\longrightarrow D_{B/P_o/A}#1$}%
}

\providecommand{\IllusieCorollaryDegreeOneCompositePOneEightyThree}[1]{%
  \scalebox{1.283}[1]{$\displaystyle
    (NL_{B/A})_1\longrightarrow(N(J/J^2))_1
    \longrightarrow(N(J/J^2))_o=J_o/J_o^2#1$}%
}

\providecommand{\IllusieCorollaryExactSequencePOneEightyThree}[1]{%
  \scalebox{1.315}[1]{$\displaystyle
    0\longrightarrow t_{-1]}N(J/J^2)\longrightarrow NL_{B/A}
    \xrightarrow{u}D_{B/P_o/A}\longrightarrow
    H_o(J/J^2)[1]\longrightarrow0#1$}%
}

\providecommand{\IllusieCorollarySpectralSequencePOneEightyThree}{%
  \scalebox{1.135}[1]{$\displaystyle
    E^2_{pq}=H_p\operatorname{Tor}^{P}_{q}(J,B)
    \Longrightarrow H_*\bigl(J\overset{L}{\otimes}_P B\bigr)=0$}%
}

% END SOURCE tex/common/corollary_truncation_p183.tex


\ReflowBodyFont 



\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:cor}{}%
\noindent \uline{Corollary} 1.3.6.\quad \uline{Let there be morphisms of rings}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:data-chain}{}%
\noindent\hspace*{136.6bp}\IllusieCorollaryDataChainPOneEightyThree{\hspace{3.0bp},}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:hypotheses}{}%
\uline{where} $P$ \uline{is almost free over} $A$\hspace{3.0bp}, \uline{and} $P\longrightarrow B$ is \uline{surjective}. \uline{Then}, \uline{in} $D(B)$, \uline{the}\par

\vspace{1.02bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:identification}{}%
\noindent \uline{truncation} $t_{[-1}L_{B/A}$ \uline{is canonically identified} with $D_{B/P/A}$\hspace{3.0bp}.
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof}{}%
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:kernel}{}%
\uline{Proof of} (1.3.5). Let $J$ be the kernel ideal of the canonical map $P\longrightarrow B$\hspace{3.0bp}. By 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:homology}{}%
(1.3.4), $H_o(D_{B/P/A})$ and $H_1(D_{B/P/A})$ are trivial simplicial $B$-modules; in\par


\noindent other words,
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:normalized-differential}{}%
\noindent\hspace*{136.5bp}\IllusieCorollaryNormalizedMapPOneEightyThree
\par

\vspace{5bp}
is an isomorphism in degree $>0$\hspace{3.0bp}. We deduce a morphism of complexes\par


\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:u}{}%
\noindent\hspace*{135.9bp}\IllusieCorollaryUMapPOneEightyThree{\hspace{3.0bp},}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:u-components}{}%
\noindent such that $u_o$ is the identity and $u_1$ is the composite
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:degree-one-composite}{}%
\noindent\hspace*{79.28bp}\IllusieCorollaryDegreeOneCompositePOneEightyThree{\hspace{3.0bp},}
\par

\vspace{5bp}
where the second arrow is the differential of $N(J/J^2)$, and the first is the inverse\par

\vspace{0.06bp}
\noindent of $(Nd_{P/A})_1$\hspace{3.0bp}. We then have an exact sequence \textsuperscript{(1)}
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:exact-sequence}{}%
\noindent\adjustbox{max width=\linewidth}{\makebox[0pt][l]{(*)}\hspace*{62.5bp}\IllusieCorollaryExactSequencePOneEightyThree{\hspace{3.0bp}.}
}\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:acyclicity}{}%
Now, since $P\longrightarrow B$ is a quasi-isomorphism, $J$ is acyclic, hence $J\overset{L}{\otimes}_PB=0$\par

\vspace{3.12bp}
\noindent (I 3.3.2). The spectral sequence (I 3.3.3.1)
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:spectral-sequence}{}%
\noindent\hspace*{134.0bp}\IllusieCorollarySpectralSequencePOneEightyThree
\par

\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:homology-vanishing}{}%
gives $H_o(J\otimes_PB)=H_1(J\otimes_PB)=0$\hspace{3.0bp}; consequently, (*) implies that $H_i u$ is an\par

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:proof:conclusion}{}%
\vspace{0.72bp}
\noindent isomorphism for $i\leq1$\hspace{3.0bp}, which completes the proof.
\par


\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S1:3:6:n1}{}%
\noindent\rule{69.7bp}{0.4bp}
\par
\ReflowBodyFont 
\noindent \textsuperscript{(1)} For the notation $t_{-1]}$, see (I 1.4.7).
\par
\vspace{5bp}

