\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S2:1:3:3:cor:flat-deformation}{}%
\uline{déformation plate de} $C_o$ \uline{sur} $B$\hspace{3bp}, \uline{i.e.} \uline{d'une} \uline{B-extension} \uline{$C$} \uline{telle que} $C$ \uline{soit} 
\uline{plat sur} $B$ \uline{et} $C\otimes_B B_o\longrightarrow C_o$ \uline{un isomorphisme.} 

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S2:1:3:3:cor:torsor}{}%
(ii)\quad \uline{Quand} $\omega(\uline{B},f_o)=0$, \uline{l'ensemble des classes d'isomorphie de déformations} 
\uline{plates de} $C_o$ \uline{sur} $B$ \uline{est un torseur sous le groupe}\quad \IllusieFlatTorsorGroupPOneEightySeven\par

