\vspace{5bp}
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S2:1:3:3:cor}{}%
\uline{Corollary} 2.1.3.3.\quad \uline{Suppose} $C_o$ \uline{is flat over} $B_o$\hspace{3bp}. \uline{Then}: 

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S2:1:3:3:cor:obstruction}{}%
(i)\quad \uline{The class} $\omega(\uline{B},f_o)$ (2.1.3.1) \uline{is the obstruction to the existence of a} 
\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S2:1:3:3:cor:flat-deformation}{}%
\uline{flat deformation of} $C_o$ \uline{over} $B$\hspace{3bp}, \uline{i.e.} \uline{of a} \uline{B-extension} \uline{$C$} \uline{such that} $C$ \uline{is} 
\uline{flat over} $B$ \uline{and} $C\otimes_B B_o\longrightarrow C_o$ \uline{is an isomorphism.} 

\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S2:1:3:3:cor:torsor}{}%
