\phantomsection\hypertarget{ILL-CCD:LNM239:CH3:S2:1:3:3:cor:automorphisms}{}%
(iii)\quad \uline{The automorphism group of a given flat deformation of} $C_o$ 
\uline{over} $B$ \uline{is canonically identified with}\quad \IllusieFlatAutomorphismGroupPOneEightySeven\ ($\simeq$\IllusieFlatAutomorphismExtPOneEightySeven\par

\noindent (II 1.2.4.3)).
\par

\vspace{5bp}
