% Every subscript o is the lowercase letter o; the obstruction symbol is Greek omega.

\providecommand{\IllusieFunctorialityEquationPOneEightySeven}{%
  \scalebox{1.153}[0.96]{$\displaystyle
    \omega(\uline{B},f_o,u)=v\,\omega(\uline{B},f_o)$}%
}

\providecommand{\IllusieFlatTorsorGroupPOneEightySeven}{%
  \scalebox{1.080}[1]{$\displaystyle
    \operatorname{Exal}_{B_o}(C_o,I\otimes_{B_o}C_o)$}%
}

\providecommand{\IllusieFlatTorsorExtPOneEightySeven}{%
  \scalebox{1.080}[1]{$\displaystyle
    \mathop{\mathbb E\mathrm{xt}}\nolimits^{1}_{C_o}
      (L_{C_o/B_o},I\otimes_{B_o}C_o)$}%
}

\providecommand{\IllusieFlatAutomorphismGroupPOneEightySeven}{%
  \scalebox{1.080}[1]{$\displaystyle
    \operatorname{Der}_{B_o}(C_o,I\otimes_{B_o}C_o)$}%
}

\providecommand{\IllusieFlatAutomorphismExtPOneEightySeven}{%
  \scalebox{1.080}[1]{$\displaystyle
    \mathop{\mathbb E\mathrm{xt}}\nolimits^{0}_{C_o}
      (L_{C_o/B_o},I\otimes_{B_o}C_o)$}%
}

\providecommand{\IllusieBaseMorphismsPOneEightySeven}[1]{%
  \scalebox{1.755}[1]{$\displaystyle
    A\longrightarrow B_o\xrightarrow{f_o}C_o#1$}%
}

\providecommand{\IllusieExtensionClassTrianglePOneEightySeven}[1]{%
  \scalebox{0.930}[0.926]{%
  \begin{tikzpicture}[baseline=(TL.base),>=stealth,x=1bp,y=1bp]
