    \node (TR) at (178,88)
      {$L_{B_o/B}\overset{L}{\otimes}_{B_o}C_o$};
    \node (B) at (178,0) {$I\otimes_{B_o}C_o$};

    \draw[->] ([xshift=6bp]TL.east) -- ([xshift=-6bp]TR.west);
    \draw[->] ([yshift=-6bp]TR.south) -- ([yshift=6bp]B.north);
    \draw[->] ([xshift=6bp,yshift=-5bp]TL.south east) --
      ([xshift=-6bp,yshift=5bp]B.north west);

    \node[anchor=west] at (245,88) {\textsuperscript{(1)}};
    \node[anchor=west] at (245,0) {#1};
  \end{tikzpicture}%
}

\providecommand{\IllusieObstructionTrianglePOneEightyEight}[1]{%
