    \draw[->] ([xshift=-3bp,yshift=-6bp]T.south) --
      node[right,pos=.64,xshift=4bp] {\scalebox{0.84}[1.50]{$\omega(\uline{B},f_o)$}}
      ([xshift=5bp,yshift=5bp]B.north east);

    \node[anchor=west] at (148,0) {#1};
  \end{tikzpicture}%
